/* dawn & dusk v0.1.0 — behaviors (plain script, load with <script defer>). Generated by scripts/build-ds.mjs; edit the files in ds/ instead. */


/* ===== behaviors/theme.js ===== */
/* Theme: dawn (light) / dusk (dark).
   - <html data-theme="dawn|dusk"> is the source of truth; the choice persists in localStorage ("dd-theme").
   - With nothing stored, the OS preference decides (tokens.css also handles that without JS).
   - Any element with [data-dd-theme-toggle] flips the theme on click. */
(() => {
  const KEY = 'dd-theme';
  const root = document.documentElement;
  const stored = (() => { try { return localStorage.getItem(KEY); } catch { return null; } })();
  if (stored === 'dawn' || stored === 'dusk') root.dataset.theme = stored;

  const current = () => root.dataset.theme || (matchMedia('(prefers-color-scheme: dark)').matches ? 'dusk' : 'dawn');
  const sync = () => document.querySelectorAll('[data-dd-theme-toggle]').forEach((b) => b.setAttribute('aria-pressed', String(current() === 'dusk')));

  // Swap in one frame: with every colour transition running at once the page repaints for --dd-dur and lags.
  const swap = (next) => {
    const off = document.createElement('style');
    off.textContent = '*,*::before,*::after{transition:none!important}';
    document.head.append(off);
    root.dataset.theme = next;
    void document.body.offsetHeight; // apply the new colours while transitions are off
    requestAnimationFrame(() => off.remove());
  };

  document.addEventListener('click', (e) => {
    if (!e.target.closest('[data-dd-theme-toggle]')) return;
    const next = current() === 'dusk' ? 'dawn' : 'dusk';
    swap(next);
    try { localStorage.setItem(KEY, next); } catch { /* storage unavailable */ }
    sync();
  });
  // The script may load deferred or late: sync now if the DOM is already there. Follow OS changes while nothing is stored.
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', sync); else sync();
  matchMedia('(prefers-color-scheme: dark)').addEventListener('change', sync);
})();


/* ===== behaviors/autoclose.js ===== */
/* Dropdowns built on <details data-dd-autoclose> (the top-bar avatar menu, the breadcrumb overflow).
   - Closes on a click outside, on Esc (focus returns to the <summary>), after choosing an item inside, and when another
     autoclose dropdown opens.
   - ↓ on the summary opens it and focuses the first item; ↑/↓ move between items while it is open. */
(() => {
  const SEL = 'details[data-dd-autoclose]';
  const items = (d) => [...d.querySelectorAll(':scope > :not(summary) :is(a[href], button:not(:disabled), [role="menuitem"])')];

  document.addEventListener('click', (e) => {
    document.querySelectorAll(`${SEL}[open]`).forEach((d) => { if (!d.contains(e.target)) d.open = false; });
    const chosen = e.target.closest(`${SEL}[open] > :not(summary) :is(a[href], button, [role="menuitem"])`);
    if (chosen) chosen.closest(SEL).open = false;
  });

  document.addEventListener('toggle', (e) => {
    const d = e.target;
    if (!(d instanceof HTMLDetailsElement) || !d.open || !d.matches(SEL)) return;
    document.querySelectorAll(`${SEL}[open]`).forEach((o) => { if (o !== d && !o.contains(d)) o.open = false; });
  }, true);

  document.addEventListener('keydown', (e) => {
    const d = e.target.closest?.(SEL);
    if (e.key === 'Escape') {
      const open = d?.open ? d : document.querySelector(`${SEL}[open]`);
      if (!open) return;
      open.open = false;
      open.querySelector('summary')?.focus();
      return;
    }
    if (!d || (e.key !== 'ArrowDown' && e.key !== 'ArrowUp')) return;
    const list = items(d);
    if (!list.length) return;
    e.preventDefault();
    if (!d.open) d.open = true;
    const i = list.indexOf(document.activeElement);
    const next = i < 0 ? (e.key === 'ArrowDown' ? 0 : list.length - 1) : (i + (e.key === 'ArrowDown' ? 1 : -1) + list.length) % list.length;
    list[next].focus();
  });
})();


/* ===== behaviors/button-group.js ===== */
/* Button group toggles: inside .dd-btn-group[data-dd-btn-toggle], a click on a button with aria-pressed flips it.
   Each button is independent (several can be pressed); for a single choice use the segmented control. */
(() => {
  document.addEventListener('click', (e) => {
    const b = e.target.closest('[data-dd-btn-toggle] [aria-pressed]');
    if (!b || b.disabled || b.getAttribute('aria-disabled') === 'true') return;
    b.setAttribute('aria-pressed', String(b.getAttribute('aria-pressed') !== 'true'));
  });
})();


/* ===== behaviors/checkbox.js ===== */
/* Checkbox helpers.
   - input[data-dd-indeterminate] starts in the mixed state (HTML has no attribute for it).
   - input[data-dd-check-all="key"] is a parent for every input[data-dd-check-in="key"]: checking it sets them all;
     changing a child updates the parent to checked, unchecked or mixed. */
(() => {
  const kids = (key) => [...document.querySelectorAll(`input[data-dd-check-in="${CSS.escape(key)}"]:not(:disabled)`)];
  const syncParent = (key) => {
    const parent = document.querySelector(`input[data-dd-check-all="${CSS.escape(key)}"]`);
    if (!parent) return;
    const list = kids(key);
    const on = list.filter((c) => c.checked).length;
    parent.checked = on > 0 && on === list.length;
    parent.indeterminate = on > 0 && on < list.length;
  };

  document.addEventListener('change', (e) => {
    const el = e.target;
    if (!(el instanceof HTMLInputElement) || el.type !== 'checkbox') return;
    if (el.dataset.ddCheckAll) {
      kids(el.dataset.ddCheckAll).forEach((c) => { c.checked = el.checked; });
      el.indeterminate = false;
    } else if (el.dataset.ddCheckIn) {
      syncParent(el.dataset.ddCheckIn);
    }
  });

  const init = () => {
    document.querySelectorAll('input[data-dd-indeterminate]').forEach((el) => { el.indeterminate = true; });
    document.querySelectorAll('input[data-dd-check-all]').forEach((el) => syncParent(el.dataset.ddCheckAll));
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();


/* ===== behaviors/chip.js ===== */
/* Chips:
   - Remove: a .dd-chip__remove button removes its chip (Enter, Space, Delete or Backspace on it works too). The chip
     gets a cancelable "dd:chip-remove" event first; focus moves to the neighbouring chip so keyboard users stay put.
   - Filter: <button class="dd-chip dd-chip--filter" aria-pressed="false"> toggles aria-pressed on click and fires
     "dd:chip-toggle" (detail.pressed).
   - Input: .dd-chip-input with a .dd-chip-input__field. Enter or a comma turns the text into a chip (colour picked
     from the Color set by the text, so a tag keeps its colour); a tag that is already there flashes instead of being
     added twice; Backspace in an empty field removes the last chip.
     The container fires "dd:chips-change" with detail.values. Icons come from the inline sprite (#dd-i-x).
   When a chip goes, the chips after it glide into its place (not under reduced motion). */
(() => {
  const still = () => matchMedia('(prefers-reduced-motion: reduce)').matches;
  const valueOf = (chip) => chip.dataset.value || chip.textContent.trim();
  const valuesIn = (box) => [...box.querySelectorAll('.dd-chip')].map(valueOf);
  const changed = (box) => box?.dispatchEvent(new CustomEvent('dd:chips-change', { bubbles: true, detail: { values: valuesIn(box) } }));

  const remove = (chip) => {
    if (!chip || chip.classList.contains('is-leaving')) return;
    if (!chip.dispatchEvent(new CustomEvent('dd:chip-remove', { bubbles: true, cancelable: true, detail: { value: valueOf(chip) } }))) return;
    const box = chip.closest('.dd-chip-input');
    const parent = chip.parentElement;
    if (chip.contains(document.activeElement)) {
      const peers = [...parent.querySelectorAll(':scope > .dd-chip:not(.is-leaving) .dd-chip__remove')];
      const i = peers.indexOf(chip.querySelector('.dd-chip__remove'));
      const next = peers[i + 1] || peers[i - 1] || box?.querySelector('.dd-chip-input__field');
      if (next) next.focus();
      else {
        // Last chip in a plain group: keep focus nearby instead of dropping it on <body>.
        if (!parent.hasAttribute('tabindex')) {
          parent.setAttribute('tabindex', '-1');
          parent.addEventListener('blur', () => parent.removeAttribute('tabindex'), { once: true });
        }
        parent.focus({ preventScroll: true });
      }
    }
    const gone = () => {
      // The chips after this one glide into the space it leaves (FLIP), even across a wrapped line.
      const rest = still() ? [] : [...parent.children].filter((c) => c !== chip);
      const before = rest.map((c) => c.getBoundingClientRect());
      chip.remove();
      rest.forEach((c, n) => {
        const r = c.getBoundingClientRect();
        const dx = before[n].left - r.left;
        const dy = before[n].top - r.top;
        if (Math.abs(dx) + Math.abs(dy) > 0.5) c.animate([{ transform: `translate(${dx}px, ${dy}px)` }, { transform: 'none' }], { duration: 160, easing: 'cubic-bezier(.45, 0, .55, 1)' });
      });
      changed(box);
    };
    if (still()) return gone();
    chip.classList.add('is-leaving');
    setTimeout(gone, 170);
  };

  const hue = (text) => { let h = 0; for (const ch of text.toLowerCase()) h = (h * 31 + ch.codePointAt(0)) >>> 0; return (h % 8) + 1; };
  const create = (text) => {
    const chip = document.createElement('span');
    chip.className = `dd-chip dd-chip--set-${hue(text)}`;
    chip.dataset.value = text;
    const label = document.createElement('span');
    label.textContent = text;
    const x = document.createElement('button');
    x.type = 'button';
    x.className = 'dd-chip__remove';
    x.setAttribute('aria-label', `Remove ${text}`);
    x.innerHTML = `<svg class="dd-icon" aria-hidden="true"><use href="${(window.dd && window.dd.iconSprite) || ''}#dd-i-x"/></svg>`;
    chip.append(label, x);
    return chip;
  };

  document.addEventListener('click', (e) => {
    const x = e.target.closest('.dd-chip__remove');
    if (x) { e.preventDefault(); remove(x.closest('.dd-chip')); return; }
    const f = e.target.closest('button.dd-chip[aria-pressed]');
    if (f) {
      const on = f.getAttribute('aria-pressed') !== 'true';
      f.setAttribute('aria-pressed', String(on));
      f.dispatchEvent(new CustomEvent('dd:chip-toggle', { bubbles: true, detail: { pressed: on } }));
      return;
    }
    const box = e.target.closest('.dd-chip-input');
    if (box && !e.target.closest('.dd-chip, input')) box.querySelector('.dd-chip-input__field')?.focus();
  });

  document.addEventListener('keydown', (e) => {
    const x = e.target.closest?.('.dd-chip__remove');
    if (x && (e.key === 'Delete' || e.key === 'Backspace')) { e.preventDefault(); remove(x.closest('.dd-chip')); return; }
    const field = e.target.closest?.('.dd-chip-input__field');
    if (!field || e.isComposing) return;
    const box = field.closest('.dd-chip-input');
    if (e.key === 'Enter' || e.key === ',') {
      const text = field.value.replace(/,/g, '').trim();
      e.preventDefault();
      if (!text) return;
      const twin = [...box.querySelectorAll('.dd-chip:not(.is-leaving)')].find((c) => valueOf(c).toLowerCase() === text.toLowerCase());
      if (twin) {
        twin.classList.remove('is-duplicate');
        void twin.offsetWidth;
        twin.classList.add('is-duplicate');
        twin.addEventListener('animationend', () => twin.classList.remove('is-duplicate'), { once: true });
      } else {
        field.before(create(text));
        changed(box);
      }
      field.value = '';
    } else if (e.key === 'Backspace' && !field.value) {
      const chips = box.querySelectorAll('.dd-chip:not(.is-leaving)');
      if (chips.length) { e.preventDefault(); remove(chips[chips.length - 1]); }
    }
  });

  window.dd = window.dd || {};
  window.dd.chip = { remove, create };
})();


/* ===== behaviors/code.js ===== */
/* Code field reveal: a button with [data-dd-code-reveal] inside .dd-code-field swaps the masked value of its
   [data-dd-code-secret] element for the secret and back. aria-pressed tracks the state; the copy button
   (data-dd-copy) always copies the real secret. Optional data-dd-code-reveal-label="Show key|Hide key". */
(() => {
  document.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-dd-code-reveal]');
    if (!btn) return;
    const field = btn.closest('.dd-code-field') || btn.parentElement;
    const value = field?.querySelector('[data-dd-code-secret]');
    if (!value) return;
    const show = btn.getAttribute('aria-pressed') !== 'true';
    if (!('ddCodeMasked' in value.dataset)) value.dataset.ddCodeMasked = value.textContent;
    value.textContent = show ? value.dataset.ddCodeSecret : value.dataset.ddCodeMasked;
    value.classList.toggle('is-revealed', show);
    btn.setAttribute('aria-pressed', String(show));
    const [showLabel, hideLabel] = (btn.dataset.ddCodeRevealLabel || 'Show value|Hide value').split('|');
    btn.setAttribute('aria-label', show ? hideLabel : showLabel);
  });
})();


/* ===== behaviors/combobox.js ===== */
/* Combobox — type to filter a listbox.
   Markup: [data-dd-combobox] (or ="multi") > .dd-input > input[role="combobox"] (+ optional [data-dd-combobox-toggle])
           and [role="listbox"] > [role="option"][data-value] (+ optional .dd-listbox__group / .dd-listbox__empty).
   Single: choosing fills the input. Multi: choosing toggles the option and adds / removes a chip
   (.dd-combobox__chip, coloured from the option's data-set="1…8" or by position). Matches are underlined.
   An optional <input type="hidden"> receives the value (comma-separated for multi).
   Fires a bubbling "dd-combobox" event with detail { value, values, option }.
   Keyboard: ↓ / ↑ open and move · Enter chooses · Esc closes, then clears · Backspace on empty removes the last chip. */
(() => {
  let uid = 0;
  const parts = (root) => ({
    input: root.querySelector('[role="combobox"]'),
    list: root.querySelector('[role="listbox"]'),
    box: root.querySelector('.dd-input'),
  });
  const multi = (root) => root.dataset.ddCombobox === 'multi';
  const options = (list) => [...list.querySelectorAll('[role="option"]')];
  const usable = (list) => options(list).filter((o) => !o.hidden && o.getAttribute('aria-disabled') !== 'true');
  const labelEl = (opt) => opt.querySelector('.dd-listbox__label') || opt;
  const labelOf = (opt) => (opt.dataset.label || labelEl(opt).dataset.text || labelEl(opt).textContent).trim();
  const valueOf = (opt) => opt.dataset.value ?? labelOf(opt);
  const esc = (s) => s.replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const icon = (name) => `<svg class="dd-icon" aria-hidden="true"><use href="#dd-i-${name}"/></svg>`;

  const setActive = (root, opt) => {
    const { input, list } = parts(root);
    list.querySelectorAll('[role="option"].is-active').forEach((o) => o.classList.remove('is-active'));
    if (!opt) { input.removeAttribute('aria-activedescendant'); return; }
    if (!opt.id) opt.id = `dd-cb-option-${++uid}`;
    opt.classList.add('is-active');
    input.setAttribute('aria-activedescendant', opt.id);
    opt.scrollIntoView({ block: 'nearest' });
  };

  const filter = (root, query) => {
    const { list } = parts(root);
    const q = query.trim().toLowerCase();
    let group = null; let groupHits = 0; let hits = 0;
    const closeGroup = () => { if (group) group.hidden = groupHits === 0; };
    for (const el of list.children) {
      if (el.classList.contains('dd-listbox__group')) { closeGroup(); group = el; groupHits = 0; continue; }
      if (el.getAttribute('role') !== 'option') continue;
      const lab = labelEl(el);
      if (lab.dataset.text === undefined) lab.dataset.text = lab.textContent;
      const text = lab.dataset.text;
      const at = q ? text.toLowerCase().indexOf(q) : -1;
      const show = !q || at >= 0 || (el.dataset.keywords || '').toLowerCase().includes(q);
      el.hidden = !show;
      lab.innerHTML = at >= 0
        ? `${esc(text.slice(0, at))}<mark class="dd-listbox__match">${esc(text.slice(at, at + q.length))}</mark>${esc(text.slice(at + q.length))}`
        : esc(text);
      if (show) { hits++; groupHits++; }
    }
    closeGroup();
    const empty = list.querySelector('.dd-listbox__empty');
    if (empty) empty.hidden = hits > 0;
    setActive(root, usable(list)[0]);
  };

  const open = (root, query) => {
    const { input, list } = parts(root);
    if (input.disabled || input.readOnly) return;
    document.querySelectorAll('[data-dd-combobox].is-open').forEach((r) => r !== root && close(r));
    if (!list.id) list.id = `dd-cb-list-${++uid}`;
    input.setAttribute('aria-controls', list.id);
    filter(root, query ?? '');
    if (!list.hidden) return;
    list.hidden = false;
    input.setAttribute('aria-expanded', 'true');
    root.classList.add('is-open');
    const selected = !multi(root) && query === undefined && list.querySelector('[role="option"][aria-selected="true"]');
    if (selected) setActive(root, selected);
  };

  const close = (root) => {
    const { input, list } = parts(root);
    if (!list || list.hidden) return;
    list.hidden = true;
    input.setAttribute('aria-expanded', 'false');
    input.removeAttribute('aria-activedescendant');
    root.classList.remove('is-open');
  };

  const sync = (root, opt) => {
    const { list } = parts(root);
    const values = options(list).filter((o) => o.getAttribute('aria-selected') === 'true').map(valueOf);
    const hidden = root.querySelector('input[type="hidden"]');
    if (hidden) { hidden.value = values.join(','); hidden.dispatchEvent(new Event('change', { bubbles: true })); }
    root.dispatchEvent(new CustomEvent('dd-combobox', { bubbles: true, detail: { value: values[0] ?? '', values, option: opt } }));
  };

  const chipFor = (root, opt) => {
    const { list } = parts(root);
    const n = opt.dataset.set || (options(list).indexOf(opt) % 8) + 1;
    const label = labelOf(opt);
    const chip = document.createElement('span');
    chip.className = 'dd-combobox__chip';
    chip.dataset.value = valueOf(opt);
    chip.style.setProperty('--dd-chip', `var(--dd-set-${n})`);
    chip.innerHTML = `<span>${esc(label)}</span><button class="dd-combobox__remove" type="button" aria-label="Remove ${esc(label)}">${icon('x')}</button>`;
    return chip;
  };

  const choose = (root, opt) => {
    if (!opt || opt.getAttribute('aria-disabled') === 'true') return;
    const { input, list, box } = parts(root);
    if (multi(root)) {
      const on = opt.getAttribute('aria-selected') !== 'true';
      opt.setAttribute('aria-selected', String(on));
      const value = valueOf(opt);
      const existing = [...box.querySelectorAll('.dd-combobox__chip')].find((c) => c.dataset.value === value);
      if (on && !existing) box.insertBefore(chipFor(root, opt), input);
      if (!on && existing) existing.remove();
      input.value = '';
      filter(root, '');
      setActive(root, opt);
      input.focus();
    } else {
      options(list).forEach((o) => o.setAttribute('aria-selected', String(o === opt)));
      input.value = labelOf(opt);
      close(root);
    }
    sync(root, opt);
  };

  const removeChip = (root, chip) => {
    const { list } = parts(root);
    const opt = options(list).find((o) => valueOf(o) === chip.dataset.value);
    if (opt) opt.setAttribute('aria-selected', 'false');
    chip.remove();
    sync(root, opt);
  };

  const move = (root, step) => {
    const { list } = parts(root);
    const opts = usable(list);
    const cur = opts.indexOf(list.querySelector('[role="option"].is-active'));
    setActive(root, opts[Math.max(0, Math.min(opts.length - 1, cur + step))]);
  };

  document.addEventListener('mousedown', (e) => {
    // Keep focus in the input while clicking options or chips.
    if (e.target.closest('[data-dd-combobox] [role="listbox"]')) e.preventDefault();
  });

  document.addEventListener('click', (e) => {
    const root = e.target.closest('[data-dd-combobox]');
    document.querySelectorAll('[data-dd-combobox].is-open').forEach((r) => r !== root && close(r));
    if (!root) return;
    const { input, list } = parts(root);
    const remove = e.target.closest('.dd-combobox__remove');
    if (remove) { removeChip(root, remove.closest('.dd-combobox__chip')); input.focus(); return; }
    if (e.target.closest('[data-dd-combobox-toggle]')) {
      if (list.hidden) open(root); else close(root);
      input.focus();
      return;
    }
    const opt = e.target.closest('[role="option"]');
    if (opt && list.contains(opt)) { choose(root, opt); return; }
    if (e.target.closest('.dd-input') && !input.disabled) { input.focus(); if (list.hidden) open(root); }
  });

  // The pointer and the keyboard share one highlight: hovering an option makes it the active one.
  document.addEventListener('mousemove', (e) => {
    const opt = e.target.closest?.('[data-dd-combobox] [role="option"]');
    if (!opt || opt.classList.contains('is-active') || opt.getAttribute('aria-disabled') === 'true') return;
    const root = opt.closest('[data-dd-combobox]');
    if (parts(root).list.contains(opt)) { const y = opt.parentElement.scrollTop; setActive(root, opt); opt.parentElement.scrollTop = y; }
  });

  document.addEventListener('input', (e) => {
    const root = e.target.closest?.('[data-dd-combobox]');
    if (!root || e.target !== parts(root).input) return;
    open(root, e.target.value);
  });

  document.addEventListener('keydown', (e) => {
    const root = e.target.closest?.('[data-dd-combobox]');
    if (!root) return;
    const { input, list, box } = parts(root);
    if (e.target !== input) return;
    const isOpen = !list.hidden;
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        if (!isOpen) open(root, multi(root) ? input.value : undefined); else move(root, 1);
        break;
      case 'ArrowUp':
        e.preventDefault();
        if (isOpen) move(root, -1);
        break;
      case 'Enter':
        if (isOpen) { e.preventDefault(); choose(root, list.querySelector('[role="option"].is-active')); }
        break;
      case 'Escape':
        if (isOpen) { e.preventDefault(); close(root); }
        else if (input.value && !multi(root)) {
          e.preventDefault();
          input.value = '';
          options(list).forEach((o) => o.setAttribute('aria-selected', 'false'));
          sync(root);
        }
        break;
      case 'Backspace':
        if (multi(root) && !input.value) {
          const chips = box.querySelectorAll('.dd-combobox__chip');
          if (chips.length) removeChip(root, chips[chips.length - 1]);
        }
        break;
      case 'Tab':
        close(root);
        break;
    }
  });

  // Single: leaving the field restores the chosen label if the typed text matches nothing.
  document.addEventListener('focusout', (e) => {
    const root = e.target.closest?.('[data-dd-combobox]');
    if (!root || (e.relatedTarget && root.contains(e.relatedTarget))) return;
    close(root);
    if (multi(root)) return;
    const { input, list } = parts(root);
    const chosen = list.querySelector('[role="option"][aria-selected="true"]');
    if (input.value && (!chosen || labelOf(chosen) !== input.value)) {
      const exact = options(list).find((o) => labelOf(o).toLowerCase() === input.value.trim().toLowerCase());
      if (exact) choose(root, exact); else input.value = chosen ? labelOf(chosen) : '';
    }
  });
})();


/* ===== behaviors/command-palette.js ===== */
/* Command palette: [data-dd-command="dialog-id"] opens that <dialog class="dd-command"> (empty value → the first one);
   ⌘K / Ctrl+K toggles the page's palette (the one marked [data-dd-hotkey], else the first). Typing filters
   .dd-command__item rows by their text and optional data-keywords; empty groups hide and .dd-command__empty shows
   (its .dd-command__query echoes the search). ↑ ↓ (or Ctrl+P / Ctrl+N) move the selected row, Enter runs it,
   Esc clears the search and then closes, a click on the backdrop closes. Running a row clicks it (links navigate),
   fires a bubbling `dd:command` event with detail { item, value } and closes the dialog. Works on inline palettes too. */
(() => {
  const ITEM = '.dd-command__item';
  let uid = 0;
  let lastFocus = null;

  const parts = (root) => ({ input: root.querySelector('.dd-command__input'), list: root.querySelector('.dd-command__list'), empty: root.querySelector('.dd-command__empty') });
  const visible = (root) => [...root.querySelectorAll(ITEM)].filter((el) => !el.closest('[hidden]') && el.getAttribute('aria-disabled') !== 'true');
  const selected = (root) => root.querySelector(`${ITEM}[aria-selected="true"]`);

  function select(root, item, scroll) {
    root.querySelectorAll(`${ITEM}[aria-selected="true"]`).forEach((el) => el.setAttribute('aria-selected', 'false'));
    const { input } = parts(root);
    if (!item) { input?.removeAttribute('aria-activedescendant'); return; }
    if (!item.id) item.id = `dd-command-item-${++uid}`;
    item.setAttribute('aria-selected', 'true');
    input?.setAttribute('aria-activedescendant', item.id);
    if (scroll) item.scrollIntoView({ block: 'nearest' });
  }

  function filter(root) {
    const { input, list, empty } = parts(root);
    const words = (input?.value || '').trim().toLowerCase().split(/\s+/).filter(Boolean);
    root.querySelectorAll(ITEM).forEach((el) => {
      const hay = `${el.textContent} ${el.dataset.keywords || ''}`.toLowerCase();
      el.hidden = !words.every((w) => hay.includes(w));
    });
    root.querySelectorAll('.dd-command__group').forEach((g) => { g.hidden = !g.querySelector(`${ITEM}:not([hidden])`); });
    const rows = visible(root);
    if (list) list.hidden = rows.length === 0;
    if (empty) {
      empty.hidden = rows.length > 0;
      empty.querySelectorAll('.dd-command__query').forEach((q) => { q.textContent = input?.value.trim() || ''; });
    }
    if (list) list.scrollTop = 0;
    select(root, rows[0], false);
  }

  function run(root, item) {
    if (!item || item.getAttribute('aria-disabled') === 'true') return;
    root.dispatchEvent(new CustomEvent('dd:command', { bubbles: true, detail: { item, value: item.dataset.value ?? item.textContent.trim() } }));
    if (root instanceof HTMLDialogElement && root.open) root.close();
  }

  function open(dialog) {
    if (!dialog || dialog.open) return;
    lastFocus = document.activeElement;
    const { input } = parts(dialog);
    if (input) { input.value = ''; input.setAttribute('role', input.getAttribute('role') || 'combobox'); input.setAttribute('aria-expanded', 'true'); }
    filter(dialog);
    dialog.showModal();
    input?.focus();
  }

  const palette = (id) => (id ? document.getElementById(id.replace(/^#/, '')) : null)
    || document.querySelector('dialog.dd-command[data-dd-hotkey]') || document.querySelector('dialog.dd-command');

  document.addEventListener('click', (e) => {
    const t = e.target.closest('[data-dd-command]');
    if (t) { e.preventDefault(); open(palette(t.getAttribute('data-dd-command'))); return; }
    // Backdrop: the click lands on the <dialog> itself, outside its content.
    if (e.target instanceof HTMLDialogElement && e.target.classList.contains('dd-command')) {
      const r = e.target.getBoundingClientRect();
      if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom) e.target.close();
      return;
    }
    const item = e.target.closest(ITEM);
    const root = item?.closest('.dd-command');
    if (root) { select(root, item, false); run(root, item); }
  });

  document.addEventListener('pointermove', (e) => {
    const item = e.target.closest?.(ITEM);
    const root = item?.closest('.dd-command');
    if (root && item !== selected(root) && item.getAttribute('aria-disabled') !== 'true') select(root, item, false);
  });

  document.addEventListener('input', (e) => {
    if (e.target.matches?.('.dd-command__input')) filter(e.target.closest('.dd-command'));
  });

  document.addEventListener('keydown', (e) => {
    // ⌘K / Ctrl+K
    if ((e.metaKey || e.ctrlKey) && !e.altKey && !e.shiftKey && e.key.toLowerCase() === 'k') {
      const d = palette();
      if (!d) return;
      e.preventDefault();
      if (d.open) d.close(); else open(d);
      return;
    }
    const root = e.target.closest?.('.dd-command');
    if (!root) return;
    const rows = visible(root);
    const i = rows.indexOf(selected(root));
    const key = e.ctrlKey && (e.key === 'n' || e.key === 'p') ? (e.key === 'n' ? 'ArrowDown' : 'ArrowUp') : e.key;
    if (key === 'ArrowDown' || key === 'ArrowUp') {
      e.preventDefault();
      if (!rows.length) return;
      const n = key === 'ArrowDown' ? (i + 1) % rows.length : (i <= 0 ? rows.length : i) - 1;
      select(root, rows[n], true);
    } else if (key === 'Enter' && e.target.matches('.dd-command__input')) {
      const item = selected(root);
      if (!item) return;
      e.preventDefault();
      item.click();
    } else if (key === 'Escape') {
      const { input } = parts(root);
      if (input?.value) { e.preventDefault(); input.value = ''; filter(root); }
    }
  });

  // Hand focus back to whatever opened the palette.
  document.addEventListener('close', (e) => {
    if (e.target.classList?.contains('dd-command') && lastFocus?.isConnected) lastFocus.focus({ preventScroll: true });
  }, true);
})();


/* ===== behaviors/copy.js ===== */
/* Copy to clipboard: [data-dd-copy="text to copy"] or [data-dd-copy-target="#id"] (copies that element's text).
   The trigger gets [data-copied] for 1.6s so CSS can show a confirmation. */
(() => {
  document.addEventListener('click', async (e) => {
    const btn = e.target.closest('[data-dd-copy], [data-dd-copy-target]');
    if (!btn) return;
    const sel = btn.getAttribute('data-dd-copy-target');
    const text = sel ? document.querySelector(sel)?.textContent ?? '' : btn.getAttribute('data-dd-copy');
    try {
      await navigator.clipboard.writeText(text.trim());
      btn.setAttribute('data-copied', '');
      setTimeout(() => btn.removeAttribute('data-copied'), 1600);
    } catch { /* clipboard blocked — leave the text selectable */ }
  });
})();


/* ===== behaviors/data-table.js ===== */
/* Data table — opt in with [data-dd-data-table] on .dd-data-table.
   - Sort: <th aria-sort="none"><button class="dd-data-table__sort">…</button></th> cycles none → ascending → descending → none.
     Rows sort within each group; expanded detail rows travel with their row. Mark numeric columns with .is-num;
     a cell's data-value (if set) is used instead of its text.
   - Select: .dd-data-table__check in the header selects every visible row (with indeterminate state); Shift-click selects a
     range. Selected rows get .is-selected; .dd-data-table__bulk shows while anything is selected and
     [data-dd-data-table-selected] receives the count. [data-dd-data-table-clear] clears the selection.
   - Expand: .dd-data-table__expand[aria-controls] toggles its detail row (hidden) and aria-expanded.
   - Filter: [data-dd-data-table-search] (text) and chips [data-dd-data-table-filter="col=value"] with aria-pressed
     (cells carry data-col="col" and optionally data-value). Same column = OR, different columns = AND.
     [data-dd-data-table-count="noun"] shows "12 services" / "3 of 12 services"; .dd-data-table__empty-row shows when
     nothing matches and [data-dd-data-table-query] receives the query. [data-dd-data-table-reset] clears filters.
   - Columns: inputs [data-dd-data-table-column="col"] show/hide the column whose <th data-col="col">.
   - Scroll: adds .is-scrolled-x / .is-scrolled-y to the root so the frozen column and sticky header cast an edge. */
(() => {
  const ROOT = '[data-dd-data-table]';
  const SKIP = '.dd-data-table__group, .dd-data-table__detail, .dd-data-table__empty-row';
  const lastClicked = new WeakMap();

  const dataRows = (root) => [...root.querySelectorAll('tbody > tr')].filter((r) => !r.matches(SKIP));
  const rowBox = (tr) => tr.querySelector('.dd-data-table__select .dd-data-table__check');
  const detailOf = (tr) => {
    const btn = tr.querySelector('.dd-data-table__expand[aria-controls]');
    return btn ? document.getElementById(btn.getAttribute('aria-controls')) : null;
  };

  // ---------- selection ----------
  function syncSelection(root) {
    const boxes = dataRows(root).map(rowBox).filter(Boolean);
    const visible = boxes.filter((b) => !b.closest('tr').hidden);
    let n = 0;
    for (const b of boxes) {
      b.closest('tr').classList.toggle('is-selected', b.checked);
      if (b.checked) n++;
    }
    const vChecked = visible.filter((b) => b.checked).length;
    const all = root.querySelector('thead .dd-data-table__check');
    if (all) {
      all.checked = visible.length > 0 && vChecked === visible.length;
      all.indeterminate = vChecked > 0 && vChecked < visible.length;
    }
    root.querySelectorAll('.dd-data-table__bulk').forEach((bar) => { bar.hidden = n === 0; });
    root.querySelectorAll('[data-dd-data-table-selected]').forEach((el) => { el.textContent = n.toLocaleString(); });
  }

  // ---------- sorting ----------
  const keyOf = (tr, i, numeric) => {
    const cell = tr.cells[i];
    if (!cell) return null;
    const raw = (cell.dataset.value ?? cell.textContent).trim();
    if (!numeric) return raw || null;
    const n = parseFloat(raw.replace(/[^\d.\-]/g, ''));
    return Number.isNaN(n) ? null : n;
  };

  function sortTable(root, th, dir) {
    const table = th.closest('table');
    const index = [...th.parentElement.cells].indexOf(th);
    const numeric = th.classList.contains('is-num') || th.dataset.type === 'number';
    for (const tbody of table.tBodies) {
      const segments = [{ head: null, units: [] }];
      const tail = [];
      [...tbody.rows].forEach((r, i) => {
        if (!r.dataset.ddOrder) r.dataset.ddOrder = String(i);
        const seg = segments[segments.length - 1];
        if (r.classList.contains('dd-data-table__group')) segments.push({ head: r, units: [] });
        else if (r.classList.contains('dd-data-table__empty-row')) tail.push(r);
        else if (r.classList.contains('dd-data-table__detail') && seg.units.length) seg.units[seg.units.length - 1].push(r);
        else seg.units.push([r]);
      });
      const cmp = (a, b) => {
        if (dir === 'none') return +a[0].dataset.ddOrder - +b[0].dataset.ddOrder;
        const ka = keyOf(a[0], index, numeric);
        const kb = keyOf(b[0], index, numeric);
        if (ka === null && kb === null) return 0;
        if (ka === null) return 1; // blanks always last
        if (kb === null) return -1;
        const d = numeric ? ka - kb : String(ka).localeCompare(String(kb), undefined, { numeric: true, sensitivity: 'base' });
        return dir === 'descending' ? -d : d;
      };
      const frag = document.createDocumentFragment();
      for (const seg of segments) {
        if (seg.head) frag.append(seg.head);
        seg.units.sort(cmp).forEach((u) => frag.append(...u));
      }
      tail.forEach((r) => frag.append(r));
      tbody.append(frag);
    }
  }

  // ---------- filtering ----------
  function applyFilter(root) {
    const input = root.querySelector('[data-dd-data-table-search]');
    const q = (input?.value || '').trim().toLowerCase();
    const active = {};
    root.querySelectorAll('[data-dd-data-table-filter][aria-pressed="true"]').forEach((chip) => {
      const [k, v] = chip.dataset.ddDataTableFilter.split('=');
      (active[k] ||= []).push(v);
    });
    const rows = dataRows(root);
    let shown = 0;
    for (const tr of rows) {
      let ok = !q || tr.textContent.toLowerCase().includes(q);
      for (const [k, vals] of Object.entries(active)) {
        const cell = tr.querySelector(`[data-col="${k}"]`);
        const v = (cell?.dataset.value ?? cell?.textContent ?? '').trim();
        if (!vals.includes(v)) ok = false;
      }
      tr.hidden = !ok;
      if (ok) shown++;
      const det = detailOf(tr);
      if (det) det.hidden = !ok || tr.querySelector('.dd-data-table__expand')?.getAttribute('aria-expanded') !== 'true';
    }
    // A group header hides when every row under it is hidden.
    for (const tbody of root.querySelectorAll('tbody')) {
      let group = null; let any = false;
      const close = () => { if (group) group.hidden = !any; };
      for (const r of tbody.rows) {
        if (r.classList.contains('dd-data-table__group')) { close(); group = r; any = false; }
        else if (!r.matches(SKIP) && !r.hidden) any = true;
      }
      close();
    }
    root.querySelectorAll('.dd-data-table__empty-row').forEach((r) => { r.hidden = shown > 0; });
    root.querySelectorAll('[data-dd-data-table-query]').forEach((el) => { el.textContent = q ? `“${input.value.trim()}”` : 'these filters'; });
    root.querySelectorAll('[data-dd-data-table-count]').forEach((el) => {
      const noun = el.dataset.ddDataTableCount || 'rows';
      el.textContent = shown === rows.length ? `${rows.length.toLocaleString()} ${noun}` : `${shown.toLocaleString()} of ${rows.length.toLocaleString()} ${noun}`;
    });
    syncSelection(root);
  }

  // ---------- column visibility ----------
  function setColumn(root, key, show) {
    const table = root.querySelector('table');
    const th = table?.querySelector(`thead th[data-col="${key}"]`);
    if (!th) return;
    const index = [...th.parentElement.cells].indexOf(th);
    for (const row of table.rows) {
      const cell = row.cells[index];
      if (cell && !cell.hasAttribute('colspan')) cell.hidden = !show;
    }
    const cols = th.parentElement.cells.length;
    const hidden = [...th.parentElement.cells].filter((c) => c.hidden).length;
    table.querySelectorAll('td[colspan], th[colspan]').forEach((c) => {
      if (!c.dataset.ddSpan) c.dataset.ddSpan = c.getAttribute('colspan');
      if (+c.dataset.ddSpan >= cols) c.setAttribute('colspan', String(cols - hidden));
    });
  }

  // ---------- events ----------
  document.addEventListener('click', (e) => {
    const root = e.target.closest(ROOT);
    if (!root) {
      document.querySelectorAll(`${ROOT} .dd-data-table__menu[open]`).forEach((d) => { d.open = false; });
      return;
    }
    root.querySelectorAll('.dd-data-table__menu[open]').forEach((d) => { if (!d.contains(e.target)) d.open = false; });

    const sort = e.target.closest('.dd-data-table__sort');
    if (sort) {
      const th = sort.closest('th');
      const next = { none: 'ascending', ascending: 'descending', descending: 'none' }[th.getAttribute('aria-sort') || 'none'];
      th.closest('tr').querySelectorAll('th[aria-sort]').forEach((h) => h.setAttribute('aria-sort', 'none'));
      th.setAttribute('aria-sort', next);
      sortTable(root, th, next);
      return;
    }

    const expand = e.target.closest('.dd-data-table__expand');
    if (expand) {
      const open = expand.getAttribute('aria-expanded') !== 'true';
      expand.setAttribute('aria-expanded', String(open));
      const det = document.getElementById(expand.getAttribute('aria-controls'));
      if (det) det.hidden = !open;
      return;
    }

    const box = e.target.closest('tbody .dd-data-table__check');
    if (box) {
      const boxes = dataRows(root).filter((r) => !r.hidden).map(rowBox).filter(Boolean);
      const prev = lastClicked.get(root);
      if (e.shiftKey && prev && boxes.includes(prev)) {
        const [a, b] = [boxes.indexOf(prev), boxes.indexOf(box)].sort((x, y) => x - y);
        boxes.slice(a, b + 1).forEach((b2) => { b2.checked = box.checked; });
      }
      lastClicked.set(root, box);
      syncSelection(root);
      return;
    }

    const chip = e.target.closest('[data-dd-data-table-filter]');
    if (chip) {
      chip.setAttribute('aria-pressed', String(chip.getAttribute('aria-pressed') !== 'true'));
      applyFilter(root);
      return;
    }

    if (e.target.closest('[data-dd-data-table-clear]')) {
      dataRows(root).map(rowBox).filter(Boolean).forEach((b) => { b.checked = false; });
      syncSelection(root);
      return;
    }

    if (e.target.closest('[data-dd-data-table-reset]')) {
      const input = root.querySelector('[data-dd-data-table-search]');
      if (input) input.value = '';
      root.querySelectorAll('[data-dd-data-table-filter]').forEach((c) => c.setAttribute('aria-pressed', 'false'));
      applyFilter(root);
    }
  });

  document.addEventListener('change', (e) => {
    const root = e.target.closest(ROOT);
    if (!root) return;
    if (e.target.matches('thead .dd-data-table__check')) {
      const on = e.target.checked;
      dataRows(root).filter((r) => !r.hidden).map(rowBox).filter(Boolean).forEach((b) => { b.checked = on; });
      syncSelection(root);
    } else if (e.target.matches('[data-dd-data-table-column]')) {
      setColumn(root, e.target.dataset.ddDataTableColumn, e.target.checked);
    }
  });

  document.addEventListener('input', (e) => {
    if (!e.target.matches('[data-dd-data-table-search]')) return;
    const root = e.target.closest(ROOT);
    if (root) applyFilter(root);
  });

  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    const menu = e.target.closest?.(`${ROOT} .dd-data-table__menu[open]`);
    if (menu) { menu.open = false; menu.querySelector('summary')?.focus(); }
  });

  document.addEventListener('scroll', (e) => {
    const el = e.target;
    if (!(el instanceof Element) || !el.classList.contains('dd-data-table__scroll')) return;
    const root = el.closest('.dd-data-table');
    root?.classList.toggle('is-scrolled-x', el.scrollLeft > 0);
    root?.classList.toggle('is-scrolled-y', el.scrollTop > 0);
  }, true);

  const init = () => document.querySelectorAll(ROOT).forEach((root) => {
    root.querySelectorAll('[data-dd-data-table-column]').forEach((inp) => { if (!inp.checked) setColumn(root, inp.dataset.ddDataTableColumn, false); });
    if (root.querySelector('[data-dd-data-table-search], [data-dd-data-table-filter], [data-dd-data-table-count]')) applyFilter(root);
    else syncSelection(root);
  });
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();


/* ===== behaviors/date-picker.js ===== */
/* Calendar + date picker.
   Calendar: [data-dd-calendar] on a .dd-calendar with data-month="YYYY-MM", data-today, data-week-start (1 = Monday,
   default; 0 = Sunday), data-min / data-max (YYYY-MM-DD), data-mode="single" (data-value) or "range"
   (data-start / data-end). The script renders the month body, moves months ([data-dd-cal-nav="-1|1"]), selects days
   and supports ← → ↑ ↓, Page Up / Down (month), Home / End (week). Fires a bubbling "dd-date" event with
   detail { value } or { start, end }.
   Date picker: [data-dd-date-picker] wraps a .dd-input (with a [data-dd-date-toggle] button) and a
   .dd-date-picker__popover holding a calendar. Choosing a day fills the input and closes; a range closes on its
   second click unless the popover has [data-dd-date-apply]. [data-start][data-end] or [data-days="7"] buttons with
   .dd-date-picker__preset set a range. Esc, a click outside or tabbing out closes. */
(() => {
  const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const DOW = ['su', 'mo', 'tu', 'we', 'th', 'fr', 'sa'];
  const DOW_LONG = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const pad = (n) => String(n).padStart(2, '0');
  const iso = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  const parse = (s) => { if (!s) return null; const [y, m, d] = s.split('-').map(Number); return y ? new Date(y, (m || 1) - 1, d || 1) : null; };
  const addDays = (d, n) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);
  const short = (d, year = true) => d.toLocaleDateString('en-US', year ? { month: 'short', day: 'numeric', year: 'numeric' } : { month: 'short', day: 'numeric' });
  const span = (a, b) => Math.round((b - a) / 864e5) + 1;
  const rangeText = (a, b) => (a.getFullYear() === b.getFullYear() ? `${short(a, false)} – ${short(b)}` : `${short(a)} – ${short(b)}`);

  // ---------- calendar ----------
  const state = (cal) => {
    const d = cal.dataset;
    const today = d.today || iso(new Date());
    return {
      month: parse(d.month || (d.value || d.start || today).slice(0, 7)),
      today, ws: Number(d.weekStart ?? 1), mode: d.mode || 'single',
      value: d.value || '', start: d.start || '', end: d.end || '', min: d.min || '', max: d.max || '',
    };
  };

  const cellClass = (s, day, hover) => {
    if (s.mode !== 'range' || !s.start) return '';
    let a = s.start; let b = s.end || hover || '';
    if (!b) return day === a ? 'is-range-start is-range-end' : '';
    if (b < a) [a, b] = [b, a];
    const preview = !s.end ? ' is-preview' : '';
    if (day === a && day === b) return 'is-range-start is-range-end';
    if (day === a) return `is-range-start${preview}`;
    if (day === b) return `is-range-end${preview}`;
    return day > a && day < b ? `is-in-range${preview}` : '';
  };

  const render = (cal, hover) => {
    const s = state(cal);
    const first = new Date(s.month.getFullYear(), s.month.getMonth(), 1);
    const lead = (first.getDay() - s.ws + 7) % 7;
    const start = addDays(first, -lead);
    const inMonth = (d) => d.getMonth() === first.getMonth();
    // Roving tabindex: selected day, else today, else the 1st — whichever is in this month.
    const anchors = [s.value, s.start, s.today].filter((v) => v && v.slice(0, 7) === iso(first).slice(0, 7));
    const focusDay = anchors[0] || iso(first);
    let rows = '';
    for (let w = 0; w < 6; w++) {
      rows += '<tr>';
      for (let k = 0; k < 7; k++) {
        const d = addDays(start, w * 7 + k);
        const day = iso(d);
        const pressed = s.mode === 'range' ? day === s.start || day === s.end : day === s.value;
        const off = (s.min && day < s.min) || (s.max && day > s.max);
        const cls = cellClass(s, day, hover);
        rows += `<td${cls ? ` class="${cls}"` : ''}><button class="dd-calendar__day${inMonth(d) ? '' : ' is-outside'}" type="button" data-date="${day}" tabindex="${day === focusDay ? 0 : -1}" aria-pressed="${pressed}"${day === s.today ? ' aria-current="date"' : ''}${off ? ' disabled' : ''}>${d.getDate()}</button></td>`;
      }
      rows += '</tr>';
    }
    const title = cal.querySelector('.dd-calendar__title');
    if (title) title.innerHTML = `${MONTHS[first.getMonth()]} <span>${first.getFullYear()}</span>`;
    const grid = cal.querySelector('.dd-calendar__grid');
    if (!grid) return;
    grid.setAttribute('aria-label', `${MONTHS[first.getMonth()]} ${first.getFullYear()}`);
    const head = `<tr>${Array.from({ length: 7 }, (_, k) => { const n = (s.ws + k) % 7; return `<th scope="col" abbr="${DOW_LONG[n]}">${DOW[n]}</th>`; }).join('')}</tr>`;
    if (!grid.tHead) grid.createTHead();
    if (grid.tHead.innerHTML !== head) grid.tHead.innerHTML = head;
    const body = grid.tBodies[0] || grid.createTBody();
    body.innerHTML = rows;
  };

  const paintHover = (cal, hover) => {
    const s = state(cal);
    if (s.mode !== 'range' || !s.start || s.end) return;
    cal.querySelectorAll('.dd-calendar__day').forEach((b) => {
      const td = b.parentElement;
      const cls = cellClass(s, b.dataset.date, hover);
      td.className = cls;
    });
  };

  const emit = (cal) => {
    const s = state(cal);
    const detail = s.mode === 'range' ? { start: s.start, end: s.end } : { value: s.value };
    cal.dispatchEvent(new CustomEvent('dd-date', { bubbles: true, detail }));
  };

  const pick = (cal, day) => {
    const d = cal.dataset;
    if ((d.mode || 'single') === 'range') {
      if (!d.start || d.end) { d.start = day; d.end = ''; }
      else if (day < d.start) { d.end = d.start; d.start = day; }
      else d.end = day;
    } else d.value = day;
    d.month = day.slice(0, 7);
    render(cal);
    cal.querySelector(`[data-date="${day}"]`)?.focus();
    emit(cal);
  };

  const shiftMonth = (cal, n) => {
    const m = state(cal).month;
    cal.dataset.month = iso(new Date(m.getFullYear(), m.getMonth() + n, 1)).slice(0, 7);
    render(cal);
  };

  const focusDate = (cal, d) => {
    const day = iso(d);
    if (!cal.querySelector(`[data-date="${day}"]:not(.is-outside)`)) { cal.dataset.month = day.slice(0, 7); render(cal); }
    const btn = cal.querySelector(`[data-date="${day}"]`);
    if (!btn) return;
    cal.querySelectorAll('.dd-calendar__day[tabindex="0"]').forEach((b) => { b.tabIndex = -1; });
    btn.tabIndex = 0;
    btn.focus();
  };

  // ---------- picker ----------
  const pickerParts = (root) => ({
    input: root.querySelector('.dd-input__control'),
    toggle: root.querySelector('[data-dd-date-toggle]'),
    pop: root.querySelector('.dd-date-picker__popover'),
    cal: root.querySelector('[data-dd-calendar]'),
  });

  const summarise = (root) => {
    const { cal } = pickerParts(root);
    const out = root.querySelector('.dd-date-picker__summary');
    if (!cal || !out) return;
    const s = state(cal);
    const a = parse(s.start); const b = parse(s.end);
    out.textContent = a && b ? `${rangeText(a, b)} · ${span(a, b)} day${span(a, b) === 1 ? '' : 's'}` : a ? `${short(a)} – pick an end date` : 'Pick a start date';
  };

  const commit = (root) => {
    const { input, cal } = pickerParts(root);
    const s = state(cal);
    if (s.mode === 'range') {
      const a = parse(s.start); const b = parse(s.end);
      if (!a || !b) return false;
      input.value = rangeText(a, b);
    } else {
      const v = parse(s.value);
      if (!v) return false;
      input.value = short(v);
    }
    const hidden = root.querySelector('input[type="hidden"]');
    if (hidden) hidden.value = s.mode === 'range' ? `${s.start}/${s.end}` : s.value;
    input.dispatchEvent(new Event('change', { bubbles: true }));
    return true;
  };

  // Keep an open popover inside the viewport: nudge it left when it would run off the right edge.
  const place = (root) => {
    const { pop } = pickerParts(root);
    if (!pop || pop.hidden || pop.classList.contains('dd-date-picker__popover--static')) return;
    pop.style.translate = '';
    const r = pop.getBoundingClientRect();
    const over = r.right - (document.documentElement.clientWidth - 8);
    if (over > 0) pop.style.translate = `${-Math.min(over, Math.max(0, r.left - 8))}px 0`;
    // On narrow screens the presets become a scrolling row: bring the active one into view.
    const row = pop.querySelector('.dd-date-picker__presets'); const on = row?.querySelector('[aria-pressed="true"]');
    if (row && on && row.scrollWidth > row.clientWidth) row.scrollLeft = on.offsetLeft - row.offsetLeft - (row.clientWidth - on.offsetWidth) / 2;
  };

  const openPicker = (root) => {
    const { toggle, pop, cal, input } = pickerParts(root);
    if (!pop || input?.disabled) return;
    document.querySelectorAll('[data-dd-date-picker].is-open').forEach((r) => r !== root && closePicker(r, false));
    pop.hidden = false;
    root.classList.add('is-open');
    toggle?.setAttribute('aria-expanded', 'true');
    if (cal) {
      root.dataset.ddSaved = JSON.stringify({ value: cal.dataset.value, start: cal.dataset.start, end: cal.dataset.end });
      const s = state(cal);
      const sel = s.value || s.start;
      if (sel) cal.dataset.month = sel.slice(0, 7);
      render(cal);
      summarise(root);
    }
    place(root);
    cal?.querySelector('.dd-calendar__day[tabindex="0"]')?.focus();
  };

  const closePicker = (root, refocus = true, revert = false) => {
    const { toggle, pop, cal } = pickerParts(root);
    if (!pop || pop.hidden) return;
    if (revert && cal && root.dataset.ddSaved) {
      const saved = JSON.parse(root.dataset.ddSaved);
      for (const k of ['value', 'start', 'end']) { if (saved[k] === undefined) delete cal.dataset[k]; else cal.dataset[k] = saved[k]; }
    }
    pop.hidden = true;
    root.classList.remove('is-open');
    toggle?.setAttribute('aria-expanded', 'false');
    if (refocus) (toggle || pickerParts(root).input)?.focus();
  };

  document.addEventListener('click', (e) => {
    const t = e.target;
    const root = t.closest('[data-dd-date-picker]');
    document.querySelectorAll('[data-dd-date-picker].is-open').forEach((r) => r !== root && closePicker(r, false, true));

    const nav = t.closest('[data-dd-cal-nav]');
    if (nav) { const cal = nav.closest('[data-dd-calendar]'); if (cal) shiftMonth(cal, Number(nav.dataset.ddCalNav)); return; }

    const dayBtn = t.closest('.dd-calendar__day');
    if (dayBtn && !dayBtn.disabled) {
      const cal = dayBtn.closest('[data-dd-calendar]');
      if (!cal) return;
      pick(cal, dayBtn.dataset.date);
      if (root) {
        root.querySelectorAll('.dd-date-picker__preset[aria-pressed="true"]').forEach((p) => p.setAttribute('aria-pressed', 'false'));
        summarise(root);
        const s = state(cal);
        const done = s.mode === 'range' ? s.start && s.end : s.value;
        if (done && !root.querySelector('[data-dd-date-apply]')) { commit(root); closePicker(root, false); pickerParts(root).input?.focus(); }
      }
      return;
    }

    if (!root) return;
    const preset = t.closest('.dd-date-picker__preset');
    if (preset) {
      const { cal } = pickerParts(root);
      if (!cal) return;
      let { start, end } = preset.dataset;
      if (preset.dataset.days) {
        const today = parse(cal.dataset.today || iso(new Date()));
        end = iso(today);
        start = iso(addDays(today, -(Number(preset.dataset.days) - 1)));
      }
      Object.assign(cal.dataset, { start, end, month: end.slice(0, 7) });
      render(cal);
      root.querySelectorAll('.dd-date-picker__preset').forEach((p) => p.setAttribute('aria-pressed', String(p === preset)));
      summarise(root);
      emit(cal);
      return;
    }
    if (t.closest('[data-dd-date-toggle]') || (t.matches('.dd-input__control') && t.readOnly)) {
      if (pickerParts(root).pop.hidden) openPicker(root); else closePicker(root);
      return;
    }
    if (t.closest('[data-dd-date-apply]')) { if (commit(root)) closePicker(root); return; }
    if (t.closest('[data-dd-date-cancel]')) { closePicker(root, true, true); }
  });

  document.addEventListener('mouseover', (e) => {
    const b = e.target.closest?.('.dd-calendar__day');
    const cal = b?.closest('[data-dd-calendar][data-mode="range"]');
    if (cal && !b.disabled && cal.dataset.ddHover !== b.dataset.date) { cal.dataset.ddHover = b.dataset.date; paintHover(cal, b.dataset.date); }
  });

  document.addEventListener('keydown', (e) => {
    const root = e.target.closest?.('[data-dd-date-picker]');
    if (e.key === 'Escape' && root && !pickerParts(root).pop?.hidden) { e.preventDefault(); closePicker(root, true, true); return; }
    if (root && e.target === pickerParts(root).input && e.key === 'ArrowDown' && (e.altKey || pickerParts(root).pop?.hidden)) {
      e.preventDefault(); openPicker(root); return;
    }
    const b = e.target.closest?.('.dd-calendar__day');
    if (!b) return;
    const cal = b.closest('[data-dd-calendar]');
    const d = parse(b.dataset.date);
    const ws = Number(cal.dataset.weekStart ?? 1);
    const moves = {
      ArrowLeft: () => addDays(d, -1), ArrowRight: () => addDays(d, 1), ArrowUp: () => addDays(d, -7), ArrowDown: () => addDays(d, 7),
      PageUp: () => new Date(d.getFullYear(), d.getMonth() - 1, Math.min(d.getDate(), 28)),
      PageDown: () => new Date(d.getFullYear(), d.getMonth() + 1, Math.min(d.getDate(), 28)),
      Home: () => addDays(d, -((d.getDay() - ws + 7) % 7)), End: () => addDays(d, 6 - ((d.getDay() - ws + 7) % 7)),
    };
    if (moves[e.key]) { e.preventDefault(); focusDate(cal, moves[e.key]()); }
  });

  // Tabbing out of an open picker closes it like a click outside (pending range changes are dropped).
  document.addEventListener('focusout', (e) => {
    const root = e.target.closest?.('[data-dd-date-picker].is-open');
    if (root && e.relatedTarget && !root.contains(e.relatedTarget)) closePicker(root, false, true);
  });

  // Typed dates: anything Date can parse ("2026-10-14", "Oct 14, 2026") moves the calendar.
  document.addEventListener('change', (e) => {
    const root = e.target.closest?.('[data-dd-date-picker]');
    if (!root || e.target !== pickerParts(root).input || !e.isTrusted) return;
    const { cal } = pickerParts(root);
    const t = Date.parse(e.target.value);
    if (!cal || Number.isNaN(t) || (cal.dataset.mode || 'single') === 'range') return;
    const v = iso(new Date(t));
    Object.assign(cal.dataset, { value: v, month: v.slice(0, 7) });
    render(cal);
    e.target.value = short(parse(v));
  });

  const placeOpen = () => document.querySelectorAll('[data-dd-date-picker].is-open').forEach(place);
  addEventListener('resize', placeOpen);
  const init = () => { document.querySelectorAll('[data-dd-calendar]').forEach((c) => render(c)); placeOpen(); };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();


/* ===== behaviors/dialog.js ===== */
/* Dialog, drawer and sheet: native <dialog class="dd-dialog | dd-drawer | dd-sheet"> opened modally.
   - [data-dd-dialog-open="#id"] on any element opens that dialog with showModal() and remembers the opener.
   - [data-dd-dialog-close] inside a dialog closes it; a value (data-dd-dialog-close="delete") becomes dialog.returnValue.
   - <form method="dialog"> inside closes it on submit (after native validation) with the submitter's value.
   - A click on the backdrop closes it, unless the dialog has data-dd-dialog-backdrop="static". Esc closes (native).
   - Closing plays the exit animation (.is-closing), then calls close(); focus returns to the opener.
   - Tab / Shift+Tab wrap inside the open dialog instead of leaving for the browser's own UI.
   - Inside a role="menu" list (sheet actions / choices): ↑ ↓ move between rows, Home / End jump to the ends.
   - Global: dd.dialog.open('#id'), dd.dialog.close('#id', value). Listen for the native "close" event for the result. */
(() => {
  const SEL = 'dialog.dd-dialog, dialog.dd-drawer, dialog.dd-sheet';
  const openers = new WeakMap();
  const pending = new WeakMap(); // dialog → cancels its in-flight exit animation
  const resolve = (target) => (typeof target === 'string' ? document.querySelector(target) : target);

  const open = (dlg, opener) => {
    if (!(dlg instanceof HTMLDialogElement) || dlg.open) return;
    pending.get(dlg)?.();
    dlg.classList.remove('is-closing');
    dlg.returnValue = '';
    openers.set(dlg, opener || document.activeElement);
    dlg.showModal();
  };

  const close = (dlg, value) => {
    if (!(dlg instanceof HTMLDialogElement) || !dlg.open || dlg.classList.contains('is-closing')) return;
    let timer;
    const stop = () => { clearTimeout(timer); dlg.removeEventListener('animationend', onEnd); pending.delete(dlg); };
    const finish = () => {
      stop();
      dlg.classList.remove('is-closing');
      if (value == null) dlg.close(); else dlg.close(String(value));
    };
    const onEnd = (e) => { if (e.target === dlg && !e.pseudoElement) finish(); };
    dlg.classList.add('is-closing');
    const name = getComputedStyle(dlg).animationName;
    if (!name || name === 'none') { finish(); return; }
    dlg.addEventListener('animationend', onEnd);
    pending.set(dlg, stop);
    timer = setTimeout(finish, 700); // fallback if the animation never ends
  };

  // Backdrop: only when the press both started and ended outside the dialog's box (so drag-selecting text is safe).
  const outside = (dlg, e) => {
    const r = dlg.getBoundingClientRect();
    return e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom;
  };
  let pressedBackdrop = null;
  document.addEventListener('pointerdown', (e) => {
    const t = e.target;
    pressedBackdrop = t instanceof HTMLDialogElement && t.matches(SEL) && outside(t, e) ? t : null;
  });

  document.addEventListener('click', (e) => {
    const opener = e.target.closest('[data-dd-dialog-open]');
    if (opener) {
      const dlg = resolve(opener.getAttribute('data-dd-dialog-open'));
      if (dlg) { e.preventDefault(); open(dlg, opener); }
      return;
    }
    const closer = e.target.closest('[data-dd-dialog-close]');
    if (closer) {
      const dlg = closer.closest(SEL);
      if (dlg) { e.preventDefault(); close(dlg, closer.getAttribute('data-dd-dialog-close') || undefined); }
      return;
    }
    const t = e.target;
    if (t instanceof HTMLDialogElement && t.matches(SEL) && t.open && pressedBackdrop === t && outside(t, e)
      && t.getAttribute('data-dd-dialog-backdrop') !== 'static') close(t);
    pressedBackdrop = null;
  });

  // Esc: animate instead of the instant native close.
  document.addEventListener('cancel', (e) => {
    const dlg = e.target;
    if (!(dlg instanceof HTMLDialogElement) || !dlg.matches(SEL)) return;
    e.preventDefault();
    close(dlg);
  }, true);

  // <form method="dialog">: animate, keep the submitter's value.
  document.addEventListener('submit', (e) => {
    const form = e.target;
    if (!(form instanceof HTMLFormElement) || form.method !== 'dialog') return;
    const dlg = form.closest(SEL);
    if (!dlg) return;
    e.preventDefault();
    close(dlg, e.submitter && e.submitter.value ? e.submitter.value : undefined);
  });

  // Focus trap: Tab past the last control wraps to the first (and Shift+Tab back), so focus never leaves the modal.
  const TABBABLE = 'a[href], button, input:not([type="hidden"]), select, textarea, summary, [tabindex], [contenteditable="true"]';
  const tabbables = (dlg) => [...dlg.querySelectorAll(TABBABLE)].filter((el) => el.tabIndex >= 0 && !el.disabled
    && !el.closest('[inert], details:not([open]) > :not(summary)') && el.getClientRects().length && getComputedStyle(el).visibility !== 'hidden');
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Tab' || e.altKey || e.ctrlKey || e.metaKey) return;
    const modal = (d) => { try { return d.matches(':modal'); } catch { return d.open; } };
    const dlg = [...document.querySelectorAll(SEL)].reverse().find((d) => d.open && modal(d));
    if (!dlg) return;
    const list = tabbables(dlg);
    if (!list.length) { e.preventDefault(); dlg.focus(); return; }
    const first = list[0], last = list[list.length - 1], at = document.activeElement;
    const outside = !dlg.contains(at) || at === dlg;
    if (e.shiftKey && (at === first || outside)) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && (at === last || outside)) { e.preventDefault(); first.focus(); }
  });

  // Arrow keys move through role="menu" rows inside an open dialog / sheet.
  document.addEventListener('keydown', (e) => {
    if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(e.key)) return;
    const item = e.target.closest?.('[role^="menuitem"]');
    const menu = item?.closest('[role="menu"]');
    if (!menu || !item.closest(SEL)) return;
    const rows = [...menu.querySelectorAll('[role^="menuitem"]')].filter((r) => !r.disabled && r.getAttribute('aria-disabled') !== 'true');
    let i = rows.indexOf(item);
    if (e.key === 'ArrowDown') i = (i + 1) % rows.length;
    else if (e.key === 'ArrowUp') i = (i - 1 + rows.length) % rows.length;
    else i = e.key === 'Home' ? 0 : rows.length - 1;
    e.preventDefault();
    rows[i]?.focus();
  });

  // Focus goes back to whatever opened the dialog.
  document.addEventListener('close', (e) => {
    const dlg = e.target;
    if (!(dlg instanceof HTMLDialogElement) || !dlg.matches(SEL)) return;
    const back = openers.get(dlg);
    openers.delete(dlg);
    if (back && back.isConnected && typeof back.focus === 'function') back.focus({ preventScroll: true });
  }, true);

  window.dd = window.dd || {};
  window.dd.dialog = { open: (target) => open(resolve(target)), close: (target, value) => close(resolve(target), value) };
})();


/* ===== behaviors/dismiss.js ===== */
/* Dismiss: a [data-dd-dismiss] button closes the alert, banner, callout or [data-dd-dismissible] element it sits in,
   or the element its value names (data-dd-dismiss="#promo"). The target first gets a cancelable "dd:dismiss" event
   (call preventDefault() to keep it), then fades, collapses and is removed. dd.dismiss(el) does the same from code. */
(() => {
  const TARGETS = '.dd-alert, .dd-banner, .dd-callout, [data-dd-dismissible]';
  const still = () => matchMedia('(prefers-reduced-motion: reduce)').matches;

  const dismiss = (el) => {
    if (!el || el.hasAttribute('data-dd-leaving')) return;
    if (!el.dispatchEvent(new CustomEvent('dd:dismiss', { bubbles: true, cancelable: true }))) return;
    el.setAttribute('data-dd-leaving', '');
    // Keep keyboard users where they were: if focus was inside, hand it to the parent instead of dropping it on <body>.
    const hadFocus = el.contains(document.activeElement);
    const done = () => {
      const parent = el.parentElement;
      el.remove();
      if (hadFocus && parent) {
        const temp = !parent.hasAttribute('tabindex');
        if (temp) {
          parent.setAttribute('tabindex', '-1');
          parent.addEventListener('blur', () => parent.removeAttribute('tabindex'), { once: true });
        }
        parent.focus({ preventScroll: true });
      }
    };
    if (still() || !el.animate) return done();
    const cs = getComputedStyle(el);
    const from = { height: `${el.offsetHeight}px`, paddingTop: cs.paddingTop, paddingBottom: cs.paddingBottom, marginTop: cs.marginTop, marginBottom: cs.marginBottom };
    // In a stacked flex/grid parent the gap next to the element goes too, or the rest would jump by one gap at the end.
    const end = { height: '0px', paddingTop: '0px', paddingBottom: '0px', marginTop: '0px', marginBottom: '0px', opacity: 0 };
    const pcs = el.parentElement ? getComputedStyle(el.parentElement) : null;
    const stacked = pcs && (pcs.display.includes('grid') || (pcs.display.includes('flex') && pcs.flexDirection.startsWith('column')));
    const gap = stacked ? parseFloat(pcs.rowGap) || 0 : 0;
    if (gap && el.nextElementSibling) end.marginBottom = `${-gap}px`;
    else if (gap && el.previousElementSibling) end.marginTop = `${-gap}px`;
    el.style.overflow = 'hidden';
    el.style.pointerEvents = 'none';
    el.animate([
      { ...from, opacity: 1 },
      { ...from, opacity: 0, offset: 0.45 },
      end,
    ], { duration: 320, easing: 'cubic-bezier(.45, 0, .55, 1)' }).finished.then(done, done);
  };

  document.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-dd-dismiss]');
    if (!btn) return;
    const sel = btn.getAttribute('data-dd-dismiss');
    const target = sel ? document.querySelector(sel) : btn.closest(TARGETS);
    if (!target) return;
    e.preventDefault();
    dismiss(target);
  });

  window.dd = window.dd || {};
  window.dd.dismiss = dismiss;
})();


/* ===== behaviors/file-upload.js ===== */
/* File upload.
   - [data-dd-dropzone] (a .dd-dropzone label around an <input type="file">) gets .is-dragover while files hover it;
     dropped files are handed to the input, which fires "change".
   - data-dd-dropzone="#listId" lists the chosen files in that .dd-file-list (name, size, a remove button).
   - [data-dd-file-remove] inside a .dd-file removes that row (with a short exit animation). */
(() => {
  const size = (b) => (b < 1024 ? `${b} B` : b < 1048576 ? `${(b / 1024).toFixed(1)} KB` : `${(b / 1048576).toFixed(1)} MB`);
  const esc = (s) => s.replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const icon = (n) => `<svg class="dd-icon" aria-hidden="true"><use href="#dd-i-${n}"/></svg>`;
  const kind = (name) => {
    const ext = (name.split('.').pop() || '').toLowerCase();
    if (/^(png|jpe?g|gif|webp|svg|avif)$/.test(ext)) return ['is-image', ext];
    if (/^(pdf|docx?|md|txt)$/.test(ext)) return ['is-doc', ext];
    if (/^(csv|json|ya?ml|sql|parquet)$/.test(ext)) return ['is-data', ext];
    if (/^(js|ts|css|html|sh|py|go|rs)$/.test(ext)) return ['is-code', ext];
    return ['', ext.slice(0, 4)];
  };
  const zoneOf = (e) => e.target.closest?.('[data-dd-dropzone]');

  // Drag state: count enter/leave pairs so moving over children doesn't flicker.
  const depth = new WeakMap();
  document.addEventListener('dragenter', (e) => {
    const z = zoneOf(e); if (!z) return;
    e.preventDefault();
    depth.set(z, (depth.get(z) || 0) + 1);
    z.classList.add('is-dragover');
  });
  document.addEventListener('dragover', (e) => { const z = zoneOf(e); if (z) { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; } });
  document.addEventListener('dragleave', (e) => {
    const z = zoneOf(e); if (!z) return;
    const n = (depth.get(z) || 1) - 1;
    depth.set(z, n);
    if (n <= 0) z.classList.remove('is-dragover');
  });
  document.addEventListener('drop', (e) => {
    const z = zoneOf(e); if (!z) return;
    e.preventDefault();
    depth.set(z, 0);
    z.classList.remove('is-dragover');
    const input = z.querySelector('input[type="file"]');
    if (!input || input.disabled || !e.dataTransfer?.files?.length) return;
    try {
      const dt = new DataTransfer();
      [...e.dataTransfer.files].slice(0, input.multiple ? undefined : 1).forEach((f) => dt.items.add(f));
      input.files = dt.files;
    } catch { return; }
    input.dispatchEvent(new Event('change', { bubbles: true }));
  });

  document.addEventListener('change', (e) => {
    const input = e.target;
    if (!(input instanceof HTMLInputElement) || input.type !== 'file') return;
    const z = input.closest('[data-dd-dropzone]');
    const target = z?.dataset.ddDropzone;
    const list = target ? document.querySelector(target) : null;
    if (!list) return;
    for (const f of input.files) {
      const [cls, ext] = kind(f.name);
      const li = document.createElement('li');
      li.className = 'dd-file is-done is-new';
      li.innerHTML = `<span class="dd-file__icon ${cls}"${ext ? ` data-ext="${esc(ext)}"` : ''}>${icon('file')}</span>
        <span class="dd-file__body"><span class="dd-file__name">${esc(f.name)}</span>
        <span class="dd-file__meta"><span>${size(f.size)}</span><span class="dd-file__status">${icon('check')}Ready</span></span></span>
        <span class="dd-file__actions"><button class="dd-btn dd-btn--ghost dd-btn--icon dd-btn--sm" type="button" data-dd-file-remove aria-label="Remove ${esc(f.name)}">${icon('x')}</button></span>`;
      list.append(li);
    }
  });

  document.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-dd-file-remove]');
    if (!btn) return;
    const row = btn.closest('.dd-file');
    if (!row) return;
    const list = row.parentElement;
    const next = row.nextElementSibling?.querySelector('[data-dd-file-remove]') || row.previousElementSibling?.querySelector('[data-dd-file-remove]');
    row.classList.add('is-removing');
    // Focus moves to the neighbouring remove button, or back to the list's dropzone once the list is empty.
    const zone = list?.id ? document.querySelector(`[data-dd-dropzone="#${CSS.escape(list.id)}"] input[type="file"]`) : null;
    const done = () => { row.remove(); (next || zone)?.focus(); list?.dispatchEvent(new CustomEvent('dd-file-remove', { bubbles: true })); };
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) done(); else row.addEventListener('animationend', done, { once: true });
  });
})();


/* ===== behaviors/form-field.js ===== */
/* Form field counter: a .dd-field__counter inside a .dd-field counts the characters of the field's control.
   The limit comes from data-dd-counter="280" (a soft limit: typing past it marks the field invalid) or from the
   control's maxlength (a hard limit). The counter gets .is-near at 90% and .is-over past the limit, and re-counts
   when its form is reset. */
(() => {
  const update = (field) => {
    const counter = field.querySelector('.dd-field__counter');
    const control = field.querySelector('input, textarea');
    if (!counter || !control) return;
    const soft = Number(counter.dataset.ddCounter) || 0;
    const max = soft || Number(control.getAttribute('maxlength')) || 0;
    const n = control.value.length;
    counter.textContent = max ? `${n} / ${max}` : String(n);
    counter.classList.toggle('is-near', !!max && n >= max * 0.9 && n <= max);
    counter.classList.toggle('is-over', !!max && n > max);
    // A soft limit marks the control invalid while it is over, and only clears what it set itself.
    if (soft && n > max) { control.setAttribute('aria-invalid', 'true'); control.dataset.ddOver = ''; }
    else if ('ddOver' in control.dataset) { control.removeAttribute('aria-invalid'); delete control.dataset.ddOver; }
  };

  document.addEventListener('input', (e) => {
    const field = e.target.closest?.('.dd-field');
    if (field && field.querySelector('.dd-field__counter')) update(field);
  });
  // A form reset restores values without firing input: re-count once the browser has put the defaults back.
  document.addEventListener('reset', (e) => {
    const form = e.target;
    if (!(form instanceof HTMLFormElement)) return;
    setTimeout(() => form.querySelectorAll('.dd-field__counter').forEach((c) => { const f = c.closest('.dd-field'); if (f) update(f); }));
  });
  const init = () => document.querySelectorAll('.dd-field__counter').forEach((c) => update(c.closest('.dd-field')));
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();


/* ===== behaviors/guide-cue.js ===== */
/* Guide cue: a short onboarding tour, one cue per step.
     <button data-dd-guide-start="deploys">Take the tour</button>
     <div class="dd-guide-cue" popover="manual" role="dialog" aria-labelledby="…"
          data-dd-guide="deploys" data-dd-guide-target="#new-deploy" data-dd-placement="bottom">
       <span class="dd-guide-cue__arrow"></span>
       <p class="dd-guide-cue__step"></p>            ← filled with "1 of 3" (or its .dd-guide-cue__count; empty
                                                     .dd-guide-cue__pips get one pip per step)
       <h3 class="dd-guide-cue__title">…</h3> <p class="dd-guide-cue__text">…</p>
       <div class="dd-guide-cue__actions"><button data-dd-guide-dismiss>Skip tour</button><button data-dd-guide-next>Next</button></div>
     </div>
   Steps run in document order. Next on the last step finishes the tour; Esc or [data-dd-guide-dismiss] ends it early.
   Each step scrolls its target into view, rings it, drops a beacon on it and points the arrow at it. Focus moves to
   the cue and returns to the start button at the end. Events on document: "dd:guide-step" (detail.index) and
   "dd:guide-end" (detail.completed). From code: dd.guide.start(name, trigger) · dd.guide.next() · dd.guide.end(). */
(() => {
  let tour = null;
  const still = () => matchMedia('(prefers-reduced-motion: reduce)').matches;

  // Place a fixed element beside an anchor: flip to the other side if it doesn't fit, keep it 8px inside the
  // viewport and aim --dd-arrow-x / --dd-arrow-y at the anchor's centre.
  const place = (el, anchor, want = 'bottom', gap = 14) => {
    let [side, align = 'center'] = want.split('-');
    const a = anchor.getBoundingClientRect();
    const w = el.offsetWidth;
    const h = el.offsetHeight;
    const vw = document.documentElement.clientWidth;
    const vh = window.innerHeight;
    const m = 8;
    const room = { top: a.top - gap - h >= m, bottom: a.bottom + gap + h <= vh - m, left: a.left - gap - w >= m, right: a.right + gap + w <= vw - m };
    const flip = { top: 'bottom', bottom: 'top', left: 'right', right: 'left' };
    if (!room[side]) side = room[flip[side]] ? flip[side] : (side === 'left' || side === 'right') ? (room.bottom ? 'bottom' : 'top') : side;
    let x;
    let y;
    if (side === 'top' || side === 'bottom') {
      y = side === 'top' ? a.top - gap - h : a.bottom + gap;
      x = align === 'start' ? a.left : align === 'end' ? a.right - w : a.left + a.width / 2 - w / 2;
      x = Math.min(Math.max(x, m), vw - w - m);
      el.style.setProperty('--dd-arrow-x', `${Math.min(Math.max(a.left + a.width / 2 - x, 16), w - 16)}px`);
    } else {
      x = side === 'left' ? a.left - gap - w : a.right + gap;
      y = align === 'start' ? a.top : align === 'end' ? a.bottom - h : a.top + a.height / 2 - h / 2;
      y = Math.min(Math.max(y, m), vh - h - m);
      el.style.setProperty('--dd-arrow-y', `${Math.min(Math.max(a.top + a.height / 2 - y, 16), h - 16)}px`);
    }
    el.style.left = `${Math.round(x)}px`;
    el.style.top = `${Math.round(y)}px`;
    el.dataset.placement = align === 'center' ? side : `${side}-${align}`;
  };

  const targetOf = (cue) => document.querySelector(cue.dataset.ddGuideTarget || '');
  const showCue = (cue) => { if (cue.showPopover) { if (!cue.matches(':popover-open')) cue.showPopover(); } else cue.hidden = false; };
  const hideCue = (cue) => { if (cue.hidePopover) { if (cue.matches(':popover-open')) cue.hidePopover(); } else cue.hidden = true; };

  const layout = () => {
    if (!tour) return;
    const cue = tour.steps[tour.i];
    const target = cue && targetOf(cue);
    if (!target) return;
    place(cue, target, cue.dataset.ddPlacement || 'bottom');
    const r = target.getBoundingClientRect();
    tour.beacon.style.left = `${Math.round(r.right - 2)}px`;
    tour.beacon.style.top = `${Math.round(r.top + 2)}px`;
  };

  const go = (i) => {
    if (!tour) return;
    const prev = tour.steps[tour.i];
    if (prev) { hideCue(prev); targetOf(prev)?.removeAttribute('data-dd-guide-active'); }
    const cue = tour.steps[i];
    if (!cue) return end(true);
    tour.i = i;
    const target = targetOf(cue);
    if (!target) return go(i + 1);
    const step = cue.querySelector('.dd-guide-cue__step');
    const count = cue.querySelector('.dd-guide-cue__count') || (step && !step.children.length ? step : null);
    if (count) count.textContent = `${i + 1} of ${tour.steps.length}`;
    const pips = cue.querySelector('.dd-guide-cue__pips');
    if (pips) pips.replaceChildren(...tour.steps.map((_, k) => Object.assign(document.createElement('i'), { className: k < i ? 'is-done' : k === i ? 'is-current' : '' })));
    if (!cue.hasAttribute('tabindex')) cue.setAttribute('tabindex', '-1');
    target.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: still() ? 'auto' : 'smooth' });
    target.setAttribute('data-dd-guide-active', '');
    const scope = target.closest('[data-theme]');
    if (scope && scope !== document.documentElement) tour.beacon.dataset.theme = scope.dataset.theme;
    showCue(cue);
    layout();
    // Smooth scrolling may still be moving the target; settle the position once it stops.
    setTimeout(layout, 350);
    cue.focus({ preventScroll: true });
    document.dispatchEvent(new CustomEvent('dd:guide-step', { detail: { name: tour.name, index: i, cue } }));
  };

  const start = (name, trigger) => {
    end(false, true);
    const steps = [...document.querySelectorAll('.dd-guide-cue[data-dd-guide]')].filter((c) => c.dataset.ddGuide === name);
    if (!steps.length) return;
    const beacon = document.createElement('span');
    beacon.className = 'dd-guide-beacon';
    beacon.setAttribute('aria-hidden', 'true');
    document.body.append(beacon);
    tour = { name, steps, i: -1, trigger: trigger || document.activeElement, beacon };
    go(0);
  };

  function end(completed = false, quiet = false) {
    if (!tour) return;
    const t = tour;
    tour = null;
    const cue = t.steps[t.i];
    if (cue) { hideCue(cue); targetOf(cue)?.removeAttribute('data-dd-guide-active'); }
    t.beacon.remove();
    if (!quiet) {
      t.trigger?.focus?.({ preventScroll: true });
      document.dispatchEvent(new CustomEvent('dd:guide-end', { detail: { name: t.name, completed } }));
    }
  }

  document.addEventListener('click', (e) => {
    const s = e.target.closest('[data-dd-guide-start]');
    if (s) { start(s.getAttribute('data-dd-guide-start'), s); return; }
    if (!tour) return;
    if (e.target.closest('[data-dd-guide-next]')) go(tour.i + 1);
    else if (e.target.closest('[data-dd-guide-back]')) go(Math.max(0, tour.i - 1));
    else if (e.target.closest('[data-dd-guide-dismiss]')) end(false);
  });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && tour) { e.preventDefault(); end(false); } });
  window.addEventListener('scroll', layout, { capture: true, passive: true });
  window.addEventListener('resize', layout, { passive: true });

  window.dd = window.dd || {};
  window.dd.guide = { start, next: () => tour && go(tour.i + 1), back: () => tour && go(Math.max(0, tour.i - 1)), end: () => end(false) };
})();


/* ===== behaviors/json-viewer.js ===== */
/* JSON viewer: renders [data-dd-json-viewer] from its inline <script type="application/json"> into a collapsible tree.
   - data-depth="2" sets how many levels start expanded (root = level 0).
   - Click a row to select it: the bar shows its path ($.replicas[0].region) and the copy button copies it.
   - Keyboard (WAI-ARIA tree): ↑/↓ move, → expand / first child, ← collapse / parent, Enter/Space toggle, Home/End.
   - dd.jsonViewer(el, data, { depth, label }) renders any value programmatically. */
(() => {
  const dd = (window.dd = window.dd || {});
  const C = 'dd-json-viewer';
  const icon = (n) => `<svg class="dd-icon" aria-hidden="true"><use href="#dd-i-${n}"/></svg>`;
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
  const ident = /^[A-Za-z_$][\w$]*$/;
  const childPath = (path, key, isArr) => (isArr ? `${path}[${key}]` : ident.test(key) ? `${path}.${key}` : `${path}[${JSON.stringify(key)}]`);
  const plural = (n, w) => `${n} ${w}${n === 1 ? '' : 's'}`;

  function node(key, value, path, depth, maxDepth, isIndex) {
    const li = document.createElement('li');
    li.className = `${C}__node`;
    li.setAttribute('role', 'treeitem');
    li.tabIndex = -1;
    li.dataset.path = path;
    const label = key === null ? ''
      : `<span class="${C}__${isIndex ? 'index' : 'key'}">${esc(key)}</span><span class="${C}__colon">:</span>`;
    const isObj = value !== null && typeof value === 'object';
    const entries = isObj ? (Array.isArray(value) ? value.map((v, i) => [i, v]) : Object.entries(value)) : [];

    if (!isObj || entries.length === 0) {
      const type = value === null ? 'null' : isObj ? 'empty' : typeof value;
      const text = isObj ? (Array.isArray(value) ? '[]' : '{}') : type === 'string' ? `"${esc(value)}"` : esc(String(value));
      li.innerHTML = `<div class="${C}__row"><span class="${C}__spacer"></span>${label}<span class="${C}__value ${C}__value--${type === 'empty' ? 'null' : type}">${text}</span></div>`;
      return li;
    }

    const arr = Array.isArray(value);
    const [open, close] = arr ? ['[', ']'] : ['{', '}'];
    li.setAttribute('aria-expanded', String(depth < maxDepth));
    li.innerHTML = `<div class="${C}__row"><span class="${C}__toggle" aria-hidden="true"></span>${label}`
      + `<span class="${C}__brace">${open}</span><span class="${C}__preview" aria-hidden="true">…${close}</span>`
      + `<span class="${C}__count">${arr ? plural(entries.length, 'item') : plural(entries.length, 'key')}</span></div>`;
    const group = document.createElement('ul');
    group.className = `${C}__group`;
    group.setAttribute('role', 'group');
    for (const [k, v] of entries) group.append(node(k, v, childPath(path, k, arr), depth + 1, maxDepth, arr));
    const end = document.createElement('div');
    end.className = `${C}__close`;
    end.setAttribute('aria-hidden', 'true');
    end.textContent = close;
    li.append(group, end);
    return li;
  }

  function select(root, item, focus = true) {
    if (!item) return;
    root.querySelectorAll('[role="treeitem"][aria-selected]').forEach((n) => n.removeAttribute('aria-selected'));
    root.querySelectorAll('[role="treeitem"][tabindex="0"]').forEach((n) => { n.tabIndex = -1; });
    item.tabIndex = 0;
    if (focus) item.setAttribute('aria-selected', 'true');
    const path = item.dataset.path;
    const out = root.querySelector(`.${C}__path-value`);
    if (out) out.textContent = path;
    root.querySelector(`.${C}__path [data-dd-copy]`)?.setAttribute('data-dd-copy', path);
    if (focus) item.focus();
  }

  const setExpanded = (item, open) => { if (item?.hasAttribute('aria-expanded')) item.setAttribute('aria-expanded', String(open)); };
  const visible = (tree) => [...tree.querySelectorAll('[role="treeitem"]')]
    .filter((n) => !n.parentElement.closest('[role="treeitem"][aria-expanded="false"]'));

  function render(el, data, { depth = 2, label } = {}) {
    el.classList.add(C);
    el.querySelectorAll(':scope > :not(script)').forEach((n) => n.remove());
    const bar = document.createElement('div');
    bar.className = `${C}__bar`;
    bar.innerHTML = `<div class="${C}__path"><span class="${C}__path-label">Path</span>`
      + `<code class="${C}__path-value">$</code>`
      + `<button class="${C}__btn ${C}__btn--icon" type="button" data-dd-copy="$" aria-label="Copy path">${icon('copy')}${icon('check')}</button></div>`
      + `<div class="${C}__actions"><button class="${C}__btn" type="button" data-dd-json-viewer-expand>Expand all</button>`
      + `<button class="${C}__btn" type="button" data-dd-json-viewer-collapse>Collapse all</button></div>`;
    const tree = document.createElement('ul');
    tree.className = `${C}__tree`;
    tree.setAttribute('role', 'tree');
    tree.setAttribute('aria-label', label || el.getAttribute('aria-label') || 'JSON');
    tree.append(node(null, data, '$', 0, depth));
    el.append(bar, tree);
    select(el, tree.querySelector('[role="treeitem"]'), false);
    el.setAttribute('data-dd-json-viewer-ready', '');
  }

  function init() {
    document.querySelectorAll('[data-dd-json-viewer]:not([data-dd-json-viewer-ready])').forEach((el) => {
      const src = el.querySelector(':scope > script[type="application/json"]');
      if (!src) return;
      try {
        render(el, JSON.parse(src.textContent), { depth: Number(el.dataset.depth ?? 2) });
      } catch {
        el.insertAdjacentHTML('beforeend', `<p class="${C}__error">This JSON could not be parsed.</p>`);
        el.setAttribute('data-dd-json-viewer-ready', '');
      }
    });
  }

  document.addEventListener('click', (e) => {
    const root = e.target.closest(`.${C}`);
    if (!root) return;
    if (e.target.closest('[data-dd-json-viewer-expand], [data-dd-json-viewer-collapse]')) {
      const open = !!e.target.closest('[data-dd-json-viewer-expand]');
      const items = root.querySelectorAll('[role="treeitem"][aria-expanded]');
      items.forEach((n, i) => setExpanded(n, open || i === 0));
      if (!open) select(root, items[0], false);
      return;
    }
    const item = e.target.closest('[role="treeitem"]');
    if (!item || !root.contains(item)) return;
    if (e.target.closest(`.${C}__toggle, .${C}__preview`)) setExpanded(item, item.getAttribute('aria-expanded') !== 'true');
    select(root, item);
  });

  document.addEventListener('keydown', (e) => {
    const item = e.target;
    if (!(item instanceof Element) || item.getAttribute('role') !== 'treeitem' || !item.closest(`.${C}`)) return;
    const root = item.closest(`.${C}`);
    const list = visible(item.closest('[role="tree"]'));
    const i = list.indexOf(item);
    const expandable = item.hasAttribute('aria-expanded');
    const open = item.getAttribute('aria-expanded') === 'true';
    let next = null;
    switch (e.key) {
      case 'ArrowDown': next = list[i + 1]; break;
      case 'ArrowUp': next = list[i - 1]; break;
      case 'Home': next = list[0]; break;
      case 'End': next = list[list.length - 1]; break;
      case 'ArrowRight':
        if (expandable && !open) setExpanded(item, true);
        else if (expandable) next = item.querySelector('[role="treeitem"]');
        break;
      case 'ArrowLeft':
        if (expandable && open) setExpanded(item, false);
        else next = item.parentElement.closest('[role="treeitem"]');
        break;
      case 'Enter': case ' ':
        if (expandable) setExpanded(item, !open);
        break;
      default: return;
    }
    e.preventDefault();
    if (next) select(root, next);
  });

  dd.jsonViewer = (el, data, opts) => render(el, data, opts);
  dd.jsonViewer.init = init;
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();


/* ===== behaviors/log-viewer.js ===== */
/* Log viewer: [data-dd-log-viewer] wires up its bar.
   - input[data-dd-log-viewer-search]: filters lines by text and highlights matches (service and message) with <mark>. Esc clears.
   - button[data-dd-log-viewer-level="debug|info|warn|error"]: aria-pressed toggles that level.
   - button[data-dd-log-viewer-wrap]: aria-pressed toggles .is-wrapped (long messages wrap instead of scrolling).
   - [data-dd-log-viewer-count]: gets “18 of 24 lines”; [data-dd-log-viewer-empty] shows when nothing matches.
   Lines are .dd-log-viewer__line[data-level]; matches are highlighted inside .dd-log-viewer__msg. */
(() => {
  const C = 'dd-log-viewer';
  const originals = new WeakMap();
  const escRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  function highlight(msg, query) {
    if (!originals.has(msg)) originals.set(msg, msg.innerHTML);
    msg.innerHTML = originals.get(msg);
    if (!query) return;
    const re = new RegExp(escRe(query), 'gi');
    const walker = document.createTreeWalker(msg, NodeFilter.SHOW_TEXT);
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    for (const node of nodes) {
      const text = node.nodeValue;
      if (!re.test(text)) continue;
      re.lastIndex = 0;
      const frag = document.createDocumentFragment();
      let last = 0;
      for (const m of text.matchAll(re)) {
        frag.append(text.slice(last, m.index));
        const mark = document.createElement('mark');
        mark.className = `${C}__mark`;
        mark.textContent = m[0];
        frag.append(mark);
        last = m.index + m[0].length;
      }
      frag.append(text.slice(last));
      node.replaceWith(frag);
    }
  }

  function apply(root) {
    const input = root.querySelector('[data-dd-log-viewer-search]');
    const query = (input?.value || '').trim();
    const q = query.toLowerCase();
    const levels = root.querySelectorAll('[data-dd-log-viewer-level]');
    const on = new Set([...levels].filter((b) => b.getAttribute('aria-pressed') !== 'false').map((b) => b.dataset.ddLogViewerLevel));
    const lines = root.querySelectorAll(`.${C}__line`);
    let shown = 0;
    lines.forEach((line) => {
      const levelOk = !levels.length || on.has(line.dataset.level);
      const textOk = !q || line.textContent.toLowerCase().includes(q);
      line.hidden = !(levelOk && textOk);
      if (!line.hidden) shown++;
      line.querySelectorAll(`.${C}__src, .${C}__msg`).forEach((el) => highlight(el, line.hidden ? '' : query));
    });
    const count = root.querySelector('[data-dd-log-viewer-count]');
    if (count) count.textContent = shown === lines.length ? `${lines.length} lines` : `${shown} of ${lines.length} lines`;
    const empty = root.querySelector('[data-dd-log-viewer-empty]');
    if (empty) {
      empty.hidden = shown > 0;
      const what = empty.querySelector('[data-dd-log-viewer-query]');
      if (what) what.textContent = query ? `“${query}”` : 'the selected levels';
    }
    // Per-level counts on the toggles reflect the search.
    levels.forEach((b) => {
      const n = b.querySelector(`.${C}__n`);
      if (!n) return;
      const lvl = b.dataset.ddLogViewerLevel;
      n.textContent = [...lines].filter((l) => l.dataset.level === lvl && (!q || l.textContent.toLowerCase().includes(q))).length;
    });
  }

  document.addEventListener('input', (e) => {
    const input = e.target.closest?.('[data-dd-log-viewer-search]');
    const root = input?.closest('[data-dd-log-viewer]');
    if (root) apply(root);
  });

  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    const input = e.target.closest?.('[data-dd-log-viewer-search]');
    const root = input?.closest('[data-dd-log-viewer]');
    if (!root || !input.value) return;
    input.value = '';
    apply(root);
  });

  document.addEventListener('click', (e) => {
    const root = e.target.closest('[data-dd-log-viewer]');
    if (!root) return;
    const level = e.target.closest('[data-dd-log-viewer-level]');
    const wrap = e.target.closest('[data-dd-log-viewer-wrap]');
    const clear = e.target.closest('[data-dd-log-viewer-clear]');
    if (level) {
      level.setAttribute('aria-pressed', String(level.getAttribute('aria-pressed') === 'false'));
      apply(root);
    } else if (wrap) {
      const next = wrap.getAttribute('aria-pressed') !== 'true';
      wrap.setAttribute('aria-pressed', String(next));
      root.classList.toggle('is-wrapped', next);
    } else if (clear) {
      const input = root.querySelector('[data-dd-log-viewer-search]');
      if (input) input.value = '';
      root.querySelectorAll('[data-dd-log-viewer-level]').forEach((b) => b.setAttribute('aria-pressed', 'true'));
      apply(root);
    }
  });

  const init = () => document.querySelectorAll('[data-dd-log-viewer]').forEach((root) => {
    // Apply the initial search value and level toggles from the markup, and sync wrap state.
    apply(root);
    const wrap = root.querySelector('[data-dd-log-viewer-wrap]');
    if (wrap) root.classList.toggle('is-wrapped', wrap.getAttribute('aria-pressed') === 'true');
  });
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();


/* ===== behaviors/menu.js ===== */
/* Menu: a trigger with [data-dd-menu="menu-id"] toggles that .dd-menu (an empty value means the next .dd-menu sibling).
   [data-dd-contextmenu="menu-id"] on an area opens the menu at the pointer on right-click, Shift+F10 or the Menu key.
   An item inside a menu with [data-dd-menu] opens a submenu to its side. Optional [data-dd-placement] on the trigger:
   bottom-start (default) · bottom-end · top-start · top-end. Menus flip when they would leave the viewport.
   Keyboard: ↓ / ↑ on the trigger open at the first / last item; in the menu ↑ ↓ Home End move, a letter jumps,
   → opens a submenu, ← closes it, Esc closes and returns focus, Tab closes. Clicking outside closes.
   role=menuitemcheckbox toggles aria-checked; role=menuitemradio checks one per group — both keep the menu open. */
(() => {
  const ITEM = '[role="menuitem"], [role="menuitemcheckbox"], [role="menuitemradio"]';
  const GAP = 5;
  const stack = []; // open floating menus, root first: { menu, trigger, side, align, at, ret }
  let hoverTimer = 0;
  let typed = '';
  let typedAt = 0;

  const byId = (v) => (v ? document.getElementById(v.replace(/^#/, '')) : null);
  const menuFor = (trigger) => {
    const v = trigger.getAttribute('data-dd-menu');
    if (v) return byId(v);
    let n = trigger.nextElementSibling;
    while (n && !n.classList.contains('dd-menu')) n = n.nextElementSibling;
    return n;
  };
  const disabled = (el) => el.disabled || el.getAttribute('aria-disabled') === 'true';
  const itemsOf = (menu) => [...menu.querySelectorAll(ITEM)]
    .filter((el) => el.closest('.dd-menu') === menu && !disabled(el) && el.getClientRects().length);
  const entryOf = (menu) => stack.find((s) => s.menu === menu);
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(v, hi));

  function place(s, first) {
    const { menu } = s;
    if (first) menu.style.animation = 'none';
    menu.style.left = '0px';
    menu.style.top = '0px';
    menu.style.maxHeight = '';
    // Where (0, 0) actually lands — non-zero only inside a transformed ancestor.
    const zero = menu.getBoundingClientRect();
    const w = zero.width;
    let h = zero.height;
    const vw = document.documentElement.clientWidth, vh = window.innerHeight, pad = 8;
    const a = s.at ? { left: s.at.x, right: s.at.x, top: s.at.y, bottom: s.at.y } : s.trigger.getBoundingClientRect();
    const gap = s.at ? 0 : GAP;
    let x, y, side = s.side;
    if (side === 'right') {
      x = a.right - 2; y = a.top - GAP * 1.5;
      if (x + w > vw - pad) {
        if (a.left - w + 2 >= pad) { x = a.left - w + 2; side = 'left'; }
        else {
          // No room on either side (phones): drop the submenu just under its item, nudged in, so the item that
          // opened it stays visible instead of being covered.
          x = a.left + GAP * 4; y = a.bottom - 2; side = 'bottom';
          if (y + h > vh - pad && a.top - h + 2 >= pad) { y = a.top - h + 2; side = 'top'; }
        }
      }
    } else {
      x = s.align === 'end' ? a.right - w : a.left;
      const roomBelow = vh - pad - (a.bottom + gap), roomAbove = a.top - gap - pad;
      // Preferred side if it fits, else the other side if it fits, else the roomier side with a scrolling menu.
      const fits = (sd) => h <= (sd === 'top' ? roomAbove : roomBelow);
      side = fits(side) ? side : fits(side === 'top' ? 'bottom' : 'top') ? (side === 'top' ? 'bottom' : 'top') : roomAbove > roomBelow ? 'top' : 'bottom';
      const room = side === 'top' ? roomAbove : roomBelow;
      if (h > room) { h = Math.max(room, 120); menu.style.maxHeight = `${h}px`; }
      y = side === 'top' ? a.top - gap - h : a.bottom + gap;
    }
    x = clamp(x, pad, Math.max(pad, vw - pad - w));
    y = clamp(y, pad, Math.max(pad, vh - pad - h));
    menu.style.left = `${Math.round(x - zero.left)}px`;
    menu.style.top = `${Math.round(y - zero.top)}px`;
    menu.dataset.side = side;
    if (first) menu.style.animation = ''; // restarts the reveal from the final position
  }

  function closeAbove(menu) { // close every open menu stacked above `menu` (null → all)
    while (stack.length && stack[stack.length - 1].menu !== menu) {
      const s = stack.pop();
      s.menu.hidden = true;
      s.menu.classList.remove('is-floating');
      s.trigger?.setAttribute('aria-expanded', 'false');
    }
  }
  function closeAll(refocus) {
    const root = stack[0];
    closeAbove(null);
    if (refocus && root) (root.trigger || root.ret)?.focus?.({ preventScroll: true });
  }

  function open(menu, trigger, { focus = 'first', at = null, ret = null } = {}) {
    const parent = trigger?.closest('.dd-menu.is-floating') || null;
    closeAbove(parent);
    const [side0, align] = (trigger?.getAttribute('data-dd-placement') || menu.getAttribute('data-dd-placement') || 'bottom-start').split('-');
    const s = { menu, trigger: at ? null : trigger, side: parent ? 'right' : side0, align, at, ret: ret || document.activeElement };
    if (!menu.getAttribute('role')) menu.setAttribute('role', 'menu');
    if (!menu.hasAttribute('tabindex')) menu.tabIndex = -1;
    menu.hidden = false;
    menu.classList.add('is-floating');
    stack.push(s);
    s.trigger?.setAttribute('aria-expanded', 'true');
    itemsOf(menu).forEach((el) => { el.tabIndex = -1; });
    place(s, true);
    if (focus === 'none') return;
    const list = itemsOf(menu);
    const target = focus === 'last' ? list[list.length - 1] : focus === 'first' ? list[0] : null;
    (target || menu).focus({ preventScroll: true });
  }

  const toggleFromTrigger = (t, focus) => {
    const menu = menuFor(t);
    if (!menu) return;
    if (entryOf(menu)) { closeAbove(t.closest('.dd-menu.is-floating') || null); t.focus({ preventScroll: true }); }
    else open(menu, t, { focus });
  };

  const activate = (item) => {
    if (disabled(item)) return;
    const role = item.getAttribute('role');
    if (role === 'menuitemcheckbox') { item.setAttribute('aria-checked', String(item.getAttribute('aria-checked') !== 'true')); return; }
    if (role === 'menuitemradio') {
      const scope = item.closest('[role="group"]') || item.closest('.dd-menu');
      scope.querySelectorAll('[role="menuitemradio"]').forEach((r) => {
        if (r.closest('.dd-menu') === item.closest('.dd-menu')) r.setAttribute('aria-checked', String(r === item));
      });
      return;
    }
    if (item.matches('[data-dd-menu]')) return;
    if (item.closest('.dd-menu.is-floating')) closeAll(true);
  };

  // Close on a press anywhere outside the open menus and their triggers.
  document.addEventListener('pointerdown', (e) => {
    if (!stack.length || e.target.closest('.dd-menu.is-floating, [data-dd-menu]')) return;
    closeAll(false);
  }, true);

  document.addEventListener('click', (e) => {
    const t = e.target.closest('[data-dd-menu]');
    if (t && !disabled(t)) {
      e.preventDefault();
      toggleFromTrigger(t, 'first');
      return;
    }
    const item = e.target.closest(ITEM);
    if (item && item.closest('.dd-menu')) {
      if (disabled(item)) { e.preventDefault(); return; }
      activate(item);
    }
  });

  document.addEventListener('contextmenu', (e) => {
    const area = e.target.closest('[data-dd-contextmenu]');
    const menu = area && byId(area.getAttribute('data-dd-contextmenu'));
    if (!menu) return;
    e.preventDefault();
    let x = e.clientX, y = e.clientY;
    if (!x && !y) { const r = (document.activeElement || area).getBoundingClientRect(); x = r.left + 12; y = r.bottom; }
    closeAll(false);
    open(menu, area, { at: { x, y }, ret: document.activeElement });
  });

  // Hover moves focus within floating menus and opens / closes submenus after a short pause.
  document.addEventListener('pointerover', (e) => {
    const item = e.target.closest(ITEM);
    const menu = item?.closest('.dd-menu.is-floating');
    if (!menu) return;
    clearTimeout(hoverTimer);
    if (!disabled(item)) item.focus({ preventScroll: true });
    hoverTimer = setTimeout(() => {
      if (!entryOf(menu)) return;
      const sub = item.matches('[data-dd-menu]') && !disabled(item) ? menuFor(item) : null;
      if (sub && entryOf(sub)) { closeAbove(sub); return; }
      closeAbove(menu);
      if (sub) open(sub, item, { focus: 'none' });
    }, 140);
  });

  document.addEventListener('keydown', (e) => {
    const t = e.target;
    // Root trigger: ↓ / ↑ open at the first / last item.
    if (t.matches?.('[data-dd-menu]') && !t.closest('.dd-menu') && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {
      e.preventDefault();
      const menu = menuFor(t);
      if (menu && !entryOf(menu)) open(menu, t, { focus: e.key === 'ArrowUp' ? 'last' : 'first' });
      else if (menu) { const l = itemsOf(menu); (e.key === 'ArrowUp' ? l[l.length - 1] : l[0])?.focus(); }
      return;
    }
    const menu = t.closest?.('.dd-menu');
    if (!menu) return;
    const list = itemsOf(menu);
    const i = list.indexOf(t.closest(ITEM));
    const floating = menu.classList.contains('is-floating');
    const go = (n) => { e.preventDefault(); list[(n + list.length) % list.length]?.focus(); };
    switch (e.key) {
      case 'ArrowDown': return go(i < 0 ? 0 : i + 1);
      case 'ArrowUp': return go(i < 0 ? list.length - 1 : i - 1);
      case 'Home': case 'PageUp': return go(0);
      case 'End': case 'PageDown': return go(list.length - 1);
      case 'ArrowRight': {
        const it = list[i];
        if (it?.matches('[data-dd-menu]')) { e.preventDefault(); const sub = menuFor(it); if (sub) open(sub, it, { focus: 'first' }); }
        return;
      }
      case 'ArrowLeft': {
        const s = entryOf(menu);
        if (s && s.trigger?.closest('.dd-menu')) { e.preventDefault(); closeAbove(s.trigger.closest('.dd-menu')); s.trigger.focus(); }
        return;
      }
      case 'Escape': {
        if (!floating) return;
        e.preventDefault(); e.stopPropagation();
        const s = entryOf(menu);
        const parent = s?.trigger?.closest('.dd-menu.is-floating');
        if (parent) { closeAbove(parent); s.trigger.focus(); } else closeAll(true);
        return;
      }
      case 'Tab': if (floating) closeAll(true); return;
      case 'Enter': case ' ': {
        const it = t.closest(ITEM);
        if (!it) return;
        if (it.matches('[data-dd-menu]')) { e.preventDefault(); const sub = menuFor(it); if (sub) open(sub, it, { focus: 'first' }); return; }
        if (it.tagName !== 'BUTTON') { e.preventDefault(); it.click(); }
        return;
      }
      default: {
        if (e.key.length !== 1 || e.ctrlKey || e.metaKey || e.altKey) return;
        const now = Date.now();
        typed = now - typedAt > 600 ? e.key.toLowerCase() : typed + e.key.toLowerCase();
        typedAt = now;
        const label = (el) => (el.querySelector('.dd-menu__body')?.firstChild?.textContent || el.textContent).trim().toLowerCase();
        const order = [...list.slice(i + 1), ...list.slice(0, i + 1)];
        const hit = order.find((el) => label(el).startsWith(typed)) || order.find((el) => label(el).startsWith(typed[0]));
        if (hit) { e.preventDefault(); hit.focus(); }
      }
    }
  });

  // Keep anchored menus attached while the page scrolls or resizes.
  let raf = 0;
  const follow = () => {
    if (!stack.length || raf) return;
    raf = requestAnimationFrame(() => { raf = 0; stack.forEach((s) => { if (!s.at) place(s); }); });
  };
  window.addEventListener('resize', follow);
  window.addEventListener('scroll', (e) => { if (!e.target?.closest?.('.dd-menu')) follow(); }, true);

  // Fill in ARIA the markup left out.
  const init = () => document.querySelectorAll('[data-dd-menu]').forEach((t) => {
    if (!t.hasAttribute('aria-haspopup')) t.setAttribute('aria-haspopup', 'menu');
    if (!t.hasAttribute('aria-expanded')) t.setAttribute('aria-expanded', 'false');
    const m = menuFor(t);
    if (m?.id && !t.hasAttribute('aria-controls')) t.setAttribute('aria-controls', m.id);
  });
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();


/* ===== behaviors/popover.js ===== */
/* Popover: <button popovertarget="deploy-pop"> + <div class="dd-popover" id="deploy-pop" popover role="dialog">.
   The browser does the opening, Esc and outside-click closing, and puts the panel in the top layer; this script places
   it beside the button that opened it, flips it when there is no room, points .dd-popover__arrow at the button,
   keeps aria-expanded in sync and follows the button on scroll and resize.
     data-dd-placement  on the popover: bottom (default) · top · left · right, optionally -start / -end
   From code: dd.popover.open(panel, anchor) · dd.popover.close(panel) · dd.popover.toggle(panel, anchor). */
(() => {
  const anchors = new WeakMap();
  const open = new Set();

  // Place a fixed element beside an anchor: flip to the other side if it doesn't fit, keep it 8px inside the
  // viewport and aim --dd-arrow-x / --dd-arrow-y at the anchor's centre.
  const place = (el, anchor, want = 'bottom', gap = 10) => {
    let [side, align = 'center'] = want.split('-');
    const a = anchor.getBoundingClientRect();
    const w = el.offsetWidth;
    const h = el.offsetHeight;
    const vw = document.documentElement.clientWidth;
    const vh = window.innerHeight;
    const m = 8;
    const room = { top: a.top - gap - h >= m, bottom: a.bottom + gap + h <= vh - m, left: a.left - gap - w >= m, right: a.right + gap + w <= vw - m };
    const flip = { top: 'bottom', bottom: 'top', left: 'right', right: 'left' };
    if (!room[side]) side = room[flip[side]] ? flip[side] : (side === 'left' || side === 'right') ? (room.bottom ? 'bottom' : 'top') : side;
    let x;
    let y;
    if (side === 'top' || side === 'bottom') {
      y = side === 'top' ? a.top - gap - h : a.bottom + gap;
      x = align === 'start' ? a.left : align === 'end' ? a.right - w : a.left + a.width / 2 - w / 2;
      x = Math.min(Math.max(x, m), vw - w - m);
      el.style.setProperty('--dd-arrow-x', `${Math.min(Math.max(a.left + a.width / 2 - x, 14), w - 14)}px`);
    } else {
      x = side === 'left' ? a.left - gap - w : a.right + gap;
      y = align === 'start' ? a.top : align === 'end' ? a.bottom - h : a.top + a.height / 2 - h / 2;
      y = Math.min(Math.max(y, m), vh - h - m);
      el.style.setProperty('--dd-arrow-y', `${Math.min(Math.max(a.top + a.height / 2 - y, 14), h - 14)}px`);
    }
    el.style.left = `${Math.round(x)}px`;
    el.style.top = `${Math.round(y)}px`;
    el.dataset.placement = align === 'center' ? side : `${side}-${align}`;
  };

  const anchorOf = (pop) => anchors.get(pop) || document.querySelector(`[popovertarget="${CSS.escape(pop.id)}"]`);
  const reposition = (pop) => { const a = anchorOf(pop); if (a?.isConnected) place(pop, a, pop.dataset.ddPlacement || 'bottom'); };

  // Remember which button opened which popover (a panel can have several triggers).
  document.addEventListener('click', (e) => {
    const btn = e.target.closest('[popovertarget]');
    if (!btn) return;
    const pop = document.getElementById(btn.getAttribute('popovertarget'));
    if (pop?.classList.contains('dd-popover') && !pop.contains(btn)) anchors.set(pop, btn);
  }, true);

  document.addEventListener('toggle', (e) => {
    const pop = e.target;
    if (!(pop instanceof HTMLElement) || !pop.classList.contains('dd-popover')) return;
    const a = anchorOf(pop);
    if (e.newState === 'open') {
      open.add(pop);
      reposition(pop);
      a?.setAttribute('aria-expanded', 'true');
    } else {
      open.delete(pop);
      document.querySelectorAll(`[popovertarget="${CSS.escape(pop.id)}"]`).forEach((b) => { if (!pop.contains(b)) b.setAttribute('aria-expanded', 'false'); });
    }
  }, true);

  const follow = () => open.forEach(reposition);
  window.addEventListener('scroll', follow, { capture: true, passive: true });
  window.addEventListener('resize', follow, { passive: true });

  // Set the initial aria-expanded so the state is announced before the first click.
  const init = () => document.querySelectorAll('[popovertarget]').forEach((b) => {
    const pop = document.getElementById(b.getAttribute('popovertarget'));
    if (pop?.classList.contains('dd-popover') && !pop.contains(b) && !b.hasAttribute('aria-expanded')) b.setAttribute('aria-expanded', 'false');
  });
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();

  window.dd = window.dd || {};
  window.dd.popover = {
    open(pop, anchor) { if (anchor) anchors.set(pop, anchor); if (!pop.matches(':popover-open')) pop.showPopover(); },
    close(pop) { if (pop.matches(':popover-open')) pop.hidePopover(); },
    toggle(pop, anchor) { if (pop.matches(':popover-open')) this.close(pop); else this.open(pop, anchor); },
  };
})();


/* ===== behaviors/segmented-control.js ===== */
/* Segmented control (button flavour): [data-dd-segmented] holds role="radio" buttons with aria-checked.
   Click or ← → ↑ ↓ Home End choose a segment; only the chosen one is in the tab order (roving tabindex).
   On change the control fires a bubbling `dd:change` event with detail { value, item }
   (value = the item's value / data-value attribute, or its label). The radio flavour needs no script. */
(() => {
  const ITEM = '[role="radio"]';
  const off = (el) => el.disabled || el.getAttribute('aria-disabled') === 'true';
  const itemsOf = (group) => [...group.querySelectorAll(ITEM)].filter((el) => el.closest('[data-dd-segmented]') === group);

  const sync = (group) => {
    const items = itemsOf(group);
    const current = items.find((el) => el.getAttribute('aria-checked') === 'true') || items.find((el) => !off(el));
    items.forEach((el) => { el.tabIndex = el === current ? 0 : -1; if (!el.hasAttribute('aria-checked')) el.setAttribute('aria-checked', 'false'); });
    if (!group.getAttribute('role')) group.setAttribute('role', 'radiogroup');
  };

  const choose = (group, item, focus) => {
    if (!item || off(item)) return;
    const was = item.getAttribute('aria-checked') === 'true';
    itemsOf(group).forEach((el) => el.setAttribute('aria-checked', String(el === item)));
    sync(group);
    if (focus) item.focus();
    if (!was) {
      const value = item.getAttribute('value') ?? item.dataset.value ?? item.textContent.trim();
      group.dispatchEvent(new CustomEvent('dd:change', { bubbles: true, detail: { value, item } }));
    }
  };

  document.addEventListener('click', (e) => {
    const item = e.target.closest(ITEM);
    const group = item?.closest('[data-dd-segmented]');
    if (group) choose(group, item, false);
  });

  document.addEventListener('keydown', (e) => {
    const item = e.target.closest?.(ITEM);
    const group = item?.closest('[data-dd-segmented]');
    if (!group) return;
    const items = itemsOf(group).filter((el) => !off(el));
    const i = items.indexOf(item);
    const rtl = getComputedStyle(group).direction === 'rtl';
    const step = { ArrowRight: rtl ? -1 : 1, ArrowDown: 1, ArrowLeft: rtl ? 1 : -1, ArrowUp: -1 }[e.key];
    let next = null;
    if (step) next = items[(i + step + items.length) % items.length];
    else if (e.key === 'Home') next = items[0];
    else if (e.key === 'End') next = items[items.length - 1];
    if (!next) return;
    e.preventDefault();
    choose(group, next, true);
    next.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  });

  const init = () => document.querySelectorAll('[data-dd-segmented]').forEach(sync);
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();


/* ===== behaviors/select.js ===== */
/* Select menu — a button that opens a listbox of options.
   Markup: [data-dd-select] > button[aria-haspopup="listbox"] (.dd-select) + [role="listbox"] (.dd-listbox, hidden)
           > [role="option"][data-value] (aria-selected on the chosen one, aria-disabled to skip).
   The trigger's [data-dd-select-value] (or its .dd-input__control) shows the chosen option's label; an optional
   <input type="hidden"> inside the root receives the value. Fires a bubbling "dd-select" event with
   detail { value, label, option }, and "change" on the hidden input.
   Keyboard: Enter / Space / ↓ / ↑ open; ↑ ↓ Home End move; type to jump; Enter / Space choose; Esc closes. */
(() => {
  let uid = 0;
  const parts = (root) => ({
    btn: root.querySelector('[aria-haspopup="listbox"]'),
    list: root.querySelector('[role="listbox"]'),
  });
  const options = (list) => [...list.querySelectorAll('[role="option"]:not([aria-disabled="true"]):not([hidden])')];
  // Open menus: by class, or rendered open in the markup (list not hidden).
  const openRoots = () => [...document.querySelectorAll('[data-dd-select]')].filter((r) => r.classList.contains('is-open') || r.querySelector('[role="listbox"]:not([hidden])'));
  const labelOf = (opt) => (opt.dataset.label || opt.querySelector('.dd-listbox__label')?.textContent || opt.textContent).trim();

  const setActive = (list, opt) => {
    list.querySelectorAll('[role="option"].is-active').forEach((o) => o.classList.remove('is-active'));
    if (!opt) { list.removeAttribute('aria-activedescendant'); return; }
    if (!opt.id) opt.id = `dd-option-${++uid}`;
    opt.classList.add('is-active');
    list.setAttribute('aria-activedescendant', opt.id);
    opt.scrollIntoView({ block: 'nearest' });
  };

  const close = (root, refocus = true) => {
    const { btn, list } = parts(root);
    if (!list || list.hidden) return;
    list.hidden = true;
    btn.setAttribute('aria-expanded', 'false');
    root.classList.remove('is-open');
    if (refocus) btn.focus();
  };

  const open = (root, which) => {
    const { btn, list } = parts(root);
    if (!btn || !list || btn.disabled) return;
    openRoots().forEach((r) => r !== root && close(r, false));
    if (!list.id) list.id = `dd-listbox-${++uid}`;
    btn.setAttribute('aria-controls', list.id);
    list.hidden = false;
    btn.setAttribute('aria-expanded', 'true');
    root.classList.add('is-open');
    const opts = options(list);
    const selected = list.querySelector('[role="option"][aria-selected="true"]');
    setActive(list, which === 'last' ? opts.at(-1) : which === 'first' ? opts[0] : selected || opts[0]);
    list.focus({ preventScroll: true });
  };

  const choose = (root, opt) => {
    const { btn, list } = parts(root);
    if (!opt || opt.getAttribute('aria-disabled') === 'true') return;
    list.querySelectorAll('[role="option"][aria-selected="true"]').forEach((o) => o.setAttribute('aria-selected', 'false'));
    opt.setAttribute('aria-selected', 'true');
    const value = opt.dataset.value ?? labelOf(opt);
    const label = labelOf(opt);
    const out = btn.querySelector('[data-dd-select-value]') || btn.querySelector('.dd-input__control');
    if (out) {
      const icon = opt.querySelector('.dd-listbox__icon, .dd-listbox__swatch');
      out.textContent = '';
      if (icon) out.append(icon.cloneNode(true));
      out.append(label);
      out.classList.remove('dd-select__placeholder');
    }
    const hidden = root.querySelector('input[type="hidden"]');
    if (hidden) { hidden.value = value; hidden.dispatchEvent(new Event('change', { bubbles: true })); }
    root.dispatchEvent(new CustomEvent('dd-select', { bubbles: true, detail: { value, label, option: opt } }));
    close(root);
  };

  // Typeahead: letters typed within 600ms build a prefix to jump to.
  const typeahead = new WeakMap();
  const jump = (root, list, key) => {
    const t = typeahead.get(root) || { q: '', at: 0 };
    const now = Date.now();
    t.q = (now - t.at > 600 ? '' : t.q) + key.toLowerCase();
    t.at = now;
    typeahead.set(root, t);
    const opts = options(list);
    const hit = opts.find((o) => labelOf(o).toLowerCase().startsWith(t.q));
    if (hit) setActive(list, hit);
  };

  document.addEventListener('click', (e) => {
    const root = e.target.closest('[data-dd-select]');
    openRoots().forEach((r) => r !== root && close(r, false));
    if (!root) return;
    const { btn, list } = parts(root);
    if (e.target.closest('[aria-haspopup="listbox"]') === btn) {
      if (list.hidden) open(root); else close(root);
      return;
    }
    const opt = e.target.closest('[role="option"]');
    if (opt && list.contains(opt)) choose(root, opt);
  });

  document.addEventListener('mousemove', (e) => {
    const opt = e.target.closest?.('[data-dd-select] [role="option"]');
    if (opt && !opt.classList.contains('is-active') && opt.getAttribute('aria-disabled') !== 'true') {
      const list = opt.closest('[role="listbox"]');
      list.querySelectorAll('.is-active').forEach((o) => o.classList.remove('is-active'));
      opt.classList.add('is-active');
      if (!opt.id) opt.id = `dd-option-${++uid}`;
      list.setAttribute('aria-activedescendant', opt.id);
    }
  });

  document.addEventListener('keydown', (e) => {
    const root = e.target.closest?.('[data-dd-select]');
    if (!root) return;
    const { btn, list } = parts(root);
    if (e.target === btn) {
      if (['ArrowDown', 'ArrowUp'].includes(e.key)) { e.preventDefault(); open(root, e.key === 'ArrowUp' ? 'last' : undefined); }
      return;
    }
    if (e.target !== list) return;
    const opts = options(list);
    const cur = opts.indexOf(list.querySelector('[role="option"].is-active'));
    switch (e.key) {
      case 'ArrowDown': e.preventDefault(); setActive(list, opts[Math.min(cur + 1, opts.length - 1)]); break;
      case 'ArrowUp': e.preventDefault(); setActive(list, opts[Math.max(cur - 1, 0)]); break;
      case 'Home': case 'PageUp': e.preventDefault(); setActive(list, opts[0]); break;
      case 'End': case 'PageDown': e.preventDefault(); setActive(list, opts.at(-1)); break;
      case 'Enter': case ' ': e.preventDefault(); choose(root, opts[cur]); break;
      case 'Escape': e.preventDefault(); close(root); break;
      case 'Tab': close(root, false); break;
      default: if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) jump(root, list, e.key);
    }
  });

  // Losing focus to somewhere outside the menu closes it.
  document.addEventListener('focusout', (e) => {
    const root = e.target.closest?.('[data-dd-select]');
    if (root && !parts(root).list?.hidden && e.relatedTarget && !root.contains(e.relatedTarget)) close(root, false);
  });
})();


/* ===== behaviors/side-nav.js ===== */
/* Side nav (.dd-side-nav): collapse, sections and the mobile off-canvas mode.
   - [data-dd-nav-toggle] folds / unfolds the page panel of its nav (or of the nav named by its value, e.g. "#app-nav").
     A nav with an id remembers the choice in localStorage ("dd-side-nav:<id>").
   - [data-dd-nav-section="name"] on a rail item shows the pane [data-dd-nav-pane="name"]; pressing the active one again
     folds the panel, like the chevron.
   - [data-dd-nav-open="#id"] opens a nav that is off-canvas (mobile); [data-dd-nav-close] closes it. Esc, a click on the
     scrim or following a link inside also close it, and focus returns to the opener. Tabbing out of it closes it too. */
(() => {
  const KEY = (id) => `dd-side-nav:${id}`;
  const store = {
    get: (k) => { try { return localStorage.getItem(k); } catch { return null; } },
    set: (k, v) => { try { localStorage.setItem(k, v); } catch { /* storage unavailable */ } },
  };
  const navFor = (el, attr) => {
    const sel = el.getAttribute(attr);
    return (sel && sel.startsWith('#') ? document.querySelector(sel) : null) || el.closest('.dd-side-nav');
  };
  const offcanvas = (nav) => getComputedStyle(nav).position === 'fixed';
  const toggles = (nav) => [...document.querySelectorAll('[data-dd-nav-toggle]')].filter((t) => navFor(t, 'data-dd-nav-toggle') === nav);
  const openers = (nav) => [...document.querySelectorAll('[data-dd-nav-open]')].filter((t) => navFor(t, 'data-dd-nav-open') === nav);
  let opener = null;

  const syncAria = (nav) => {
    const open = !nav.classList.contains('is-collapsed');
    toggles(nav).forEach((t) => {
      t.setAttribute('aria-expanded', String(open));
      if (t.hasAttribute('data-label')) t.setAttribute('data-label', open ? 'Collapse' : 'Expand');
      if (t.hasAttribute('aria-label')) t.setAttribute('aria-label', open ? 'Collapse navigation' : 'Expand navigation');
    });
    const active = nav.querySelector('[data-dd-nav-section].is-active');
    if (active) active.setAttribute('aria-expanded', String(open));
  };

  const setCollapsed = (nav, collapsed, persist = true) => {
    nav.classList.toggle('is-collapsed', collapsed);
    syncAria(nav);
    if (persist && nav.id) store.set(KEY(nav.id), collapsed ? 'collapsed' : 'open');
  };

  const setMobile = (nav, open, trigger) => {
    nav.classList.toggle('is-mobile-open', open);
    openers(nav).forEach((b) => b.setAttribute('aria-expanded', String(open)));
    if (open) {
      opener = trigger || document.activeElement;
      const first = nav.querySelector('.dd-side-nav__pane:not([hidden]) :is([aria-current="page"], .is-active)') || nav.querySelector('.dd-side-nav__item');
      requestAnimationFrame(() => first?.focus({ preventScroll: true }));
    } else if (opener && nav.contains(document.activeElement)) {
      opener.focus({ preventScroll: true });
      opener = null;
    }
  };

  const showSection = (nav, item) => {
    const name = item.getAttribute('data-dd-nav-section');
    const pane = nav.querySelector(`[data-dd-nav-pane="${name}"]`);
    if (!pane) return;
    const wasActive = item.classList.contains('is-active') && !pane.hidden;
    if (wasActive && !offcanvas(nav)) { setCollapsed(nav, !nav.classList.contains('is-collapsed')); return; }
    nav.querySelectorAll('[data-dd-nav-section]').forEach((it) => {
      const on = it === item;
      it.classList.toggle('is-active', on);
      if (on) it.setAttribute('aria-current', 'true'); else { it.removeAttribute('aria-current'); it.removeAttribute('aria-expanded'); }
    });
    nav.querySelectorAll('[data-dd-nav-pane]').forEach((p) => { p.hidden = p !== pane; });
    if (nav.classList.contains('is-collapsed') && !offcanvas(nav)) setCollapsed(nav, false);
    else syncAria(nav);
  };

  document.addEventListener('click', (e) => {
    const t = e.target;
    const toggle = t.closest('[data-dd-nav-toggle]');
    if (toggle) {
      const nav = navFor(toggle, 'data-dd-nav-toggle');
      if (!nav) return;
      if (nav.classList.contains('is-mobile-open')) setMobile(nav, false);
      else setCollapsed(nav, !nav.classList.contains('is-collapsed'));
      return;
    }
    const open = t.closest('[data-dd-nav-open]');
    if (open) {
      const nav = navFor(open, 'data-dd-nav-open');
      if (nav) setMobile(nav, !nav.classList.contains('is-mobile-open'), open);
      return;
    }
    const close = t.closest('[data-dd-nav-close]');
    if (close) { const nav = close.closest('.dd-side-nav'); if (nav) setMobile(nav, false); return; }
    const section = t.closest('[data-dd-nav-section]');
    if (section) { const nav = section.closest('.dd-side-nav'); if (nav) { e.preventDefault(); showSection(nav, section); } return; }
    // A click on the scrim (the nav's own ::before) or on a link inside an open off-canvas nav closes it.
    if (t.matches?.('.dd-side-nav.is-mobile-open')) { setMobile(t, false); return; }
    const link = t.closest('.dd-side-nav.is-mobile-open a[href]');
    if (link) setMobile(link.closest('.dd-side-nav'), false);
  });

  // Tabbing out of an open off-canvas nav closes it, so focus never sits on the page hidden behind the scrim.
  document.addEventListener('focusin', (e) => {
    const nav = document.querySelector('.dd-side-nav.is-mobile-open');
    if (nav && !nav.contains(e.target) && !openers(nav).includes(e.target)) setMobile(nav, false);
  });

  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    const nav = document.querySelector('.dd-side-nav.is-mobile-open');
    if (nav) { e.preventDefault(); setMobile(nav, false); }
  });

  // Restore persisted collapse state without animating it.
  const restore = () => {
    document.querySelectorAll('.dd-side-nav').forEach((nav) => {
      const saved = nav.id ? store.get(KEY(nav.id)) : null;
      if (saved === 'collapsed' || saved === 'open') {
        nav.classList.add('is-restoring');
        nav.classList.toggle('is-collapsed', saved === 'collapsed');
        requestAnimationFrame(() => requestAnimationFrame(() => nav.classList.remove('is-restoring')));
      }
      syncAria(nav);
    });
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', restore); else restore();
})();


/* ===== behaviors/slider.js ===== */
/* Slider: keeps a .dd-slider's fill and labels in step with its range inputs.
   - Single: sets --_p (0–1) on the slider. Range (.dd-slider--range, two inputs): sets --_lo / --_hi and stops
     the thumbs crossing.
   - <output for="inputId"> (anywhere) shows that input's value; data-unit on the output appends a unit.
   - .dd-slider__bubble[data-for="inputId"] rides above its thumb.
   - .dd-slider__ticks > [data-value] gets .is-active when it matches a value. */
(() => {
  const frac = (el) => {
    const min = Number(el.min || 0); const max = Number(el.max || 100);
    return max === min ? 0 : (Number(el.value) - min) / (max - min);
  };
  const fmt = (el, unit = '') => `${Number(el.value).toLocaleString('en-US')}${unit}`;

  const sync = (slider, moved) => {
    const inputs = [...slider.querySelectorAll('.dd-slider__input')];
    if (!inputs.length) return;
    if (inputs.length > 1) {
      const [lo, hi] = inputs;
      if (Number(lo.value) > Number(hi.value)) { if (moved === lo) lo.value = hi.value; else hi.value = lo.value; }
      slider.style.setProperty('--_lo', frac(lo).toFixed(4));
      slider.style.setProperty('--_hi', frac(hi).toFixed(4));
      // Keep the most recently moved thumb on top so it never gets stuck under the other.
      lo.style.zIndex = moved === lo || frac(lo) > 0.98 ? 2 : 1;
    } else {
      slider.style.setProperty('--_p', frac(inputs[0]).toFixed(4));
    }
    const values = inputs.map((el) => el.value);
    inputs.forEach((el) => {
      if (!el.id) return;
      document.querySelectorAll(`output[for~="${CSS.escape(el.id)}"]`).forEach((o) => { o.textContent = fmt(el, o.dataset.unit); });
      slider.querySelectorAll(`.dd-slider__bubble[data-for="${CSS.escape(el.id)}"]`).forEach((b) => {
        b.style.setProperty('--_p', frac(el).toFixed(4));
        b.textContent = fmt(el, b.dataset.unit);
      });
    });
    slider.querySelectorAll('.dd-slider__ticks > [data-value]').forEach((t) => {
      const v = Number(t.dataset.value);
      t.classList.toggle('is-active', inputs.length > 1 ? v >= Number(values[0]) && v <= Number(values[1]) : v === Number(values[0]));
    });
  };

  document.addEventListener('input', (e) => {
    const input = e.target.closest?.('.dd-slider__input');
    if (input) sync(input.closest('.dd-slider'), input);
  });
  const init = () => document.querySelectorAll('.dd-slider').forEach((s) => sync(s));
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();


/* ===== behaviors/tabs.js ===== */
/* Tabs: [data-dd-tabs] wraps a [role="tablist"] of [role="tab"] buttons and their [role="tabpanel"]s.
   - A tab finds its panel through aria-controls, or by order when aria-controls is missing (ids are filled in).
   - Roving focus: only the selected tab is in the tab order. ←/→ (↑/↓ when the list has aria-orientation="vertical"),
     Home and End move between tabs and select them; disabled tabs are skipped.
   - Fires "dd:tabchange" on the [data-dd-tabs] element with { detail: { tab, panel } }. */
(() => {
  let uid = 0;
  const own = (root, sel) => [...root.querySelectorAll(sel)].filter((el) => el.closest('[data-dd-tabs]') === root);
  const tabsOf = (root) => own(root, '[role="tab"]');
  const panelOf = (root, tab) => {
    const id = tab.getAttribute('aria-controls');
    if (id) return document.getElementById(id);
    return own(root, '[role="tabpanel"]')[tabsOf(root).indexOf(tab)] || null;
  };
  const enabled = (t) => !t.disabled && t.getAttribute('aria-disabled') !== 'true';
  const smooth = () => (matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth');

  const select = (root, tab, { focus = false, scroll = true } = {}) => {
    let panel = null;
    tabsOf(root).forEach((t) => {
      const on = t === tab;
      t.setAttribute('aria-selected', String(on));
      t.tabIndex = on ? 0 : -1;
      const p = panelOf(root, t);
      if (p) p.hidden = !on;
      if (on) panel = p;
    });
    if (focus) tab.focus();
    if (scroll) {
      const list = tab.closest('[role="tablist"]');
      if (list && list.scrollWidth > list.clientWidth) {
        const lr = list.getBoundingClientRect(), tr = tab.getBoundingClientRect(), pad = 32;
        if (tr.left < lr.left + pad) list.scrollBy({ left: tr.left - lr.left - pad, behavior: smooth() });
        else if (tr.right > lr.right - pad) list.scrollBy({ left: tr.right - lr.right + pad, behavior: smooth() });
      }
    }
    root.dispatchEvent(new CustomEvent('dd:tabchange', { bubbles: true, detail: { tab, panel } }));
  };

  const init = (root) => {
    if (root.ddTabs) return;
    root.ddTabs = true;
    const tabs = tabsOf(root);
    if (!tabs.length) return;
    tabs.forEach((t) => {
      if (!t.id) t.id = `dd-tab-${++uid}`;
      const p = panelOf(root, t);
      if (p) {
        if (!p.id) p.id = `${t.id}-panel`;
        t.setAttribute('aria-controls', p.id);
        p.setAttribute('aria-labelledby', t.id);
        if (!p.hasAttribute('tabindex')) p.tabIndex = 0;
      }
    });
    const current = tabs.find((t) => t.getAttribute('aria-selected') === 'true') || tabs.find(enabled) || tabs[0];
    select(root, current, { scroll: false });
  };
  const initAll = () => document.querySelectorAll('[data-dd-tabs]').forEach(init);

  document.addEventListener('click', (e) => {
    const tab = e.target.closest('[data-dd-tabs] [role="tab"]');
    if (!tab || !enabled(tab)) return;
    const root = tab.closest('[data-dd-tabs]');
    init(root);
    select(root, tab);
  });

  document.addEventListener('keydown', (e) => {
    const tab = e.target.closest?.('[data-dd-tabs] [role="tab"]');
    if (!tab) return;
    const root = tab.closest('[data-dd-tabs]');
    const vertical = tab.closest('[role="tablist"]')?.getAttribute('aria-orientation') === 'vertical';
    const keys = vertical ? { ArrowUp: -1, ArrowDown: 1 } : { ArrowLeft: -1, ArrowRight: 1 };
    const list = tabsOf(root).filter(enabled);
    let i = list.indexOf(tab);
    if (e.key in keys) i = (i + keys[e.key] + list.length) % list.length;
    else if (e.key === 'Home') i = 0;
    else if (e.key === 'End') i = list.length - 1;
    else return;
    e.preventDefault();
    select(root, list[i], { focus: true });
  });

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initAll); else initAll();
  window.dd = window.dd || {};
  window.dd.tabs = { init: initAll, select: (tab) => { const root = tab?.closest('[data-dd-tabs]'); if (root) { init(root); select(root, tab); } } };
})();


/* ===== behaviors/text-input.js ===== */
/* Text input helpers, all opt-in and delegated from document:
   - [data-dd-reveal]  on a button inside .dd-input toggles its control between password and text (aria-pressed).
   - [data-dd-clear]   empties the control, fires input/change and puts focus back.
   - [data-dd-step="1"|"-1"] steps a number control (stepUp / stepDown honour min, max and step); the button is
     disabled while the value sits on that end of the range. */
(() => {
  const controlOf = (el) => el.closest('.dd-input')?.querySelector('.dd-input__control');
  const fire = (el) => {
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  };

  document.addEventListener('click', (e) => {
    const reveal = e.target.closest('[data-dd-reveal]');
    if (reveal) {
      const input = controlOf(reveal);
      if (!input) return;
      const show = input.type === 'password';
      input.type = show ? 'text' : 'password';
      reveal.setAttribute('aria-pressed', String(show));
      reveal.setAttribute('aria-label', show ? 'Hide password' : 'Show password');
      return;
    }
    const clear = e.target.closest('[data-dd-clear]');
    if (clear) {
      const input = controlOf(clear);
      if (!input) return;
      input.value = '';
      fire(input);
      input.focus();
      return;
    }
    const step = e.target.closest('[data-dd-step]');
    if (step) {
      const input = controlOf(step);
      if (!input || input.disabled || input.readOnly) return;
      try {
        if (Number(step.dataset.ddStep) < 0) input.stepDown(); else input.stepUp();
      } catch { return; }
      fire(input);
    }
  });

  // Steppers dim at the ends of the range (min / max), and come back as soon as the value moves off them.
  const limits = (input) => {
    const box = input.closest('.dd-input');
    if (!box || input.type !== 'number') return;
    const v = input.valueAsNumber; const min = parseFloat(input.min); const max = parseFloat(input.max);
    box.querySelectorAll('[data-dd-step]').forEach((b) => {
      const down = Number(b.dataset.ddStep) < 0;
      const off = input.disabled || input.readOnly || (!Number.isNaN(v) && (down ? v <= min : v >= max));
      if (off && b === document.activeElement) input.focus(); // don't strand keyboard focus on a dead button
      b.disabled = off;
    });
  };
  document.addEventListener('input', (e) => { if (e.target.matches?.('.dd-input__control[type="number"]')) limits(e.target); });
  const init = () => document.querySelectorAll('.dd-input:has([data-dd-step]) .dd-input__control[type="number"]').forEach(limits);
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();


/* ===== behaviors/textarea.js ===== */
/* Textarea auto-grow: textarea[data-dd-autogrow] resizes to its content on every input, up to its CSS max-height,
   then scrolls. (Browsers with field-sizing: content do this natively; the script keeps the others in step.) */
(() => {
  const grow = (el) => {
    el.style.height = 'auto';
    const max = parseFloat(getComputedStyle(el).maxHeight) || Infinity;
    el.style.height = `${Math.min(el.scrollHeight, max)}px`;
    el.style.overflowY = el.scrollHeight > max ? 'auto' : 'hidden';
  };
  document.addEventListener('input', (e) => { if (e.target.matches?.('textarea[data-dd-autogrow]')) grow(e.target); });
  // A form reset restores the text without an input event: regrow after the browser has put it back.
  document.addEventListener('reset', (e) => {
    if (e.target instanceof HTMLFormElement) setTimeout(() => e.target.querySelectorAll('textarea[data-dd-autogrow]').forEach(grow));
  });
  const init = () => document.querySelectorAll('textarea[data-dd-autogrow]').forEach(grow);
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();


/* ===== behaviors/toast.js ===== */
/* Toast: dd.toast({ title, description, intent, action, duration }) adds a toast to the stack at the bottom-right.
     intent    'info' (default) · 'ok' · 'warn' · 'bad' · 'neutral'
     action    { label: 'Undo', onClick(toast) {} } — clicking it runs onClick, then dismisses the toast
     duration  ms before it leaves on its own (default 5000; 0 keeps it until dismissed). A hairline shows the time
               left; hovering or focusing the stack pauses every timer, and so does hiding the tab.
   Swipe a toast sideways (or drag it with the mouse) to dismiss it; Esc dismisses the toast that has focus, and focus
   then moves to the next toast or back to where it was before the stack.
     icon      any sprite name, to override the intent's icon
   Returns { el, dismiss() }. dd.toast('Saved') works too, and dd.toast.clear() empties the stack.
   Declarative: <button data-dd-toast="Title" data-dd-toast-description="…" data-dd-toast-intent="ok"
   data-dd-toast-action="Undo" data-dd-toast-duration="8000">. The toast takes the dawn/dusk theme of the
   element that raised it, so a toast from a dusk panel is a dusk toast. Icons come from the inline sprite
   (#dd-i-NAME); set dd.iconSprite = 'icons.svg' to use an external one. */
(() => {
  window.dd = window.dd || {};
  const dd = window.dd;
  const MAX = 4;
  const ICONS = { info: 'info', ok: 'success', warn: 'alert', bad: 'danger', neutral: 'bell' };
  const still = () => matchMedia('(prefers-reduced-motion: reduce)').matches;
  const icon = (name) => {
    const ns = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(ns, 'svg');
    svg.setAttribute('class', 'dd-icon');
    svg.setAttribute('aria-hidden', 'true');
    const use = document.createElementNS(ns, 'use');
    use.setAttribute('href', `${dd.iconSprite || ''}#dd-i-${name}`);
    svg.append(use);
    return svg;
  };
  const make = (tag, cls, text) => {
    const n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  };

  const live = new Set(); // toasts with a running timer
  let stack;
  let held = false;
  let returnTo = null; // where focus was before it entered the stack
  const hold = (on) => {
    held = on;
    live.forEach((t) => (on ? t.timer?.pause() : t.timer?.play()));
  };
  const toaster = () => {
    if (stack?.isConnected) return stack;
    stack = document.querySelector('.dd-toaster');
    if (!stack) {
      stack = make('section', 'dd-toaster');
      document.body.append(stack);
    }
    stack.setAttribute('aria-label', 'Notifications');
    stack.setAttribute('aria-live', 'polite');
    stack.addEventListener('pointerenter', () => hold(true));
    stack.addEventListener('pointerleave', () => { if (!stack.contains(document.activeElement)) hold(false); });
    stack.addEventListener('focusin', (e) => {
      if (e.relatedTarget && !stack.contains(e.relatedTarget)) returnTo = e.relatedTarget;
      hold(true);
    });
    stack.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape') return;
      const t = e.target.closest?.('.dd-toast');
      if (t?.ddToast) { e.preventDefault(); t.ddToast.dismiss(); }
    });
    stack.addEventListener('focusout', (e) => { if (!stack.contains(e.relatedTarget) && !stack.matches(':hover')) hold(false); });
    return stack;
  };
  document.addEventListener('visibilitychange', () => hold(document.hidden || !!stack?.matches(':hover') || !!stack?.contains(document.activeElement)));

  // Toasts already in the stack glide to their new place instead of jumping when one is added (FLIP).
  const glide = (region, change) => {
    const kids = still() ? [] : [...region.querySelectorAll(':scope > .dd-toast:not([data-leaving])')];
    const before = kids.map((k) => k.getBoundingClientRect().top);
    change();
    kids.forEach((k, n) => {
      const dy = before[n] - k.getBoundingClientRect().top;
      if (Math.abs(dy) > 0.5) k.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 320, easing: 'cubic-bezier(.45, 0, .55, 1)', composite: 'add' });
    });
  };

  const toast = (opts = {}) => {
    if (typeof opts === 'string') opts = { title: opts };
    const { title = '', description = '', intent = 'info', action, duration = 5000, dismissible = true } = opts;
    const el = make('div', `dd-toast dd-toast--${intent}`);
    if (intent === 'bad') el.setAttribute('role', 'alert');
    const from = opts.from || document.activeElement;
    const scope = from?.closest?.('[data-theme]');
    if (scope && scope !== document.documentElement) el.dataset.theme = scope.dataset.theme;

    el.append(icon(opts.icon || ICONS[intent] || 'info'));
    const body = make('div', 'dd-toast__body');
    if (title) body.append(make('p', 'dd-toast__title', title));
    if (description) body.append(make('p', 'dd-toast__text', description));
    el.append(body);

    const handle = { el, dismiss: () => leave() };
    if (action?.label) {
      const wrap = make('div', 'dd-toast__actions');
      const btn = make('button', 'dd-toast__action', action.label);
      btn.type = 'button';
      btn.addEventListener('click', () => { action.onClick?.(handle); leave(); });
      wrap.append(btn);
      el.append(wrap);
    }
    if (dismissible) {
      const x = make('button', 'dd-toast__dismiss');
      x.type = 'button';
      x.setAttribute('aria-label', 'Dismiss notification');
      x.append(icon('x'));
      x.addEventListener('click', () => leave());
      el.append(x);
    }

    let gone = false;
    function leave() {
      if (gone) return;
      gone = true;
      // Keep keyboard users in the stack: focus the neighbouring toast, or go back to where they came from.
      // (After a mouse click focus is simply dropped, so the other timers start again when the pointer leaves.)
      if (el.contains(document.activeElement) && !document.activeElement.matches(':focus-visible')) document.activeElement.blur();
      else if (el.contains(document.activeElement)) {
        const shown = [...(el.parentElement?.querySelectorAll(':scope > .dd-toast:not([data-leaving])') || [])];
        const k = shown.indexOf(el);
        const next = (shown[k + 1] || shown[k - 1])?.querySelector('button, a[href]');
        if (next) next.focus();
        else if (returnTo?.isConnected) returnTo.focus({ preventScroll: true });
        else document.activeElement.blur();
      }
      el.dataset.leaving = '';
      handle.timer?.cancel();
      live.delete(handle);
      if (still() || !el.animate || !el.isConnected) return el.remove();
      const h = `${el.offsetHeight}px`;
      const gap = `${-(parseFloat(getComputedStyle(el.parentElement).rowGap) || 0)}px`;
      // A swiped toast leaves from where the pointer let go, in the direction it was thrown.
      const cs = getComputedStyle(el);
      const at = parseFloat(cs.translate) || 0;
      const from = `${at}px 0`;
      const away = `${at + (at < 0 ? -32 : 32)}px 0`;
      el.classList.remove('is-swiping');
      el.style.pointerEvents = 'none';
      el.animate([
        { opacity: Number(cs.opacity), translate: from, height: h, marginBottom: '0px' },
        { opacity: 0, translate: away, height: h, marginBottom: '0px', offset: 0.5 },
        { opacity: 0, translate: away, height: '0px', marginBottom: gap, paddingTop: '0px', paddingBottom: '0px' },
      ], { duration: 320, easing: 'cubic-bezier(.45, 0, .55, 1)' }).finished.then(() => el.remove(), () => el.remove());
    }

    const region = toaster();
    // A brand-new live region needs a beat before content lands in it, or screen readers miss the first toast.
    const add = () => {
      glide(region, () => region.append(el));
      const shown = [...region.querySelectorAll(':scope > .dd-toast:not([data-leaving])')];
      shown.slice(0, Math.max(0, shown.length - MAX)).forEach((old) => old.ddToast?.dismiss());
      if (duration > 0) {
        const bar = make('span', 'dd-toast__progress');
        bar.setAttribute('aria-hidden', 'true');
        el.append(bar);
        handle.timer = bar.animate([{ transform: 'scaleX(1)' }, { transform: 'scaleX(0)' }], { duration, easing: 'linear', fill: 'forwards' });
        handle.timer.finished.then(() => leave(), () => {});
        live.add(handle);
        if (held) handle.timer.pause();
      }
    };
    el.ddToast = handle;
    if (region.childElementCount || region.dataset.ready) add();
    else { region.dataset.ready = ''; requestAnimationFrame(add); }
    return handle;
  };
  toast.clear = () => document.querySelectorAll('.dd-toaster > .dd-toast').forEach((t) => (t.ddToast ? t.ddToast.dismiss() : t.remove()));
  dd.toast = toast;

  // Swipe: drag a live toast sideways; past a third of its width (or a quick flick) it leaves, otherwise it springs back.
  let drag = null;
  document.addEventListener('pointerdown', (e) => {
    const el = e.target.closest?.('.dd-toaster > .dd-toast');
    if (!el || el.dataset.leaving || e.button !== 0 || e.target.closest('button, a, input, select, textarea')) return;
    drag = { el, id: e.pointerId, x: e.clientX, y: e.clientY, dx: 0, t: performance.now(), on: false };
  });
  document.addEventListener('pointermove', (e) => {
    if (!drag || e.pointerId !== drag.id) return;
    const dx = e.clientX - drag.x;
    const dy = e.clientY - drag.y;
    if (!drag.on) {
      if (Math.abs(dy) > 10 && Math.abs(dy) > Math.abs(dx)) { drag = null; return; }
      if (Math.abs(dx) < 6) return;
      drag.on = true;
      drag.el.setPointerCapture?.(e.pointerId);
      drag.el.classList.add('is-swiping');
    }
    drag.dx = dx;
    drag.el.style.translate = `${dx}px 0`;
    drag.el.style.opacity = String(Math.max(0.15, 1 - Math.abs(dx) / (drag.el.offsetWidth * 0.8)));
  });
  const drop = (e) => {
    if (!drag || e.pointerId !== drag.id) return;
    const { el, dx, t, on } = drag;
    drag = null;
    if (!on) return;
    el.classList.remove('is-swiping');
    const fling = Math.abs(dx) / Math.max(1, performance.now() - t) > 0.6;
    if (e.type === 'pointerup' && (Math.abs(dx) > el.offsetWidth * 0.33 || (fling && Math.abs(dx) > 24)) && el.ddToast) {
      el.ddToast.dismiss(); // leaves from where it was let go
    } else {
      el.style.translate = '';
      el.style.opacity = '';
    }
  };
  document.addEventListener('pointerup', drop);
  document.addEventListener('pointercancel', drop);

  document.addEventListener('click', (e) => {
    const t = e.target.closest('[data-dd-toast]');
    if (!t) return;
    const d = t.dataset;
    toast({
      title: d.ddToast,
      description: d.ddToastDescription,
      intent: d.ddToastIntent || 'info',
      action: d.ddToastAction ? { label: d.ddToastAction } : undefined,
      duration: d.ddToastDuration != null ? Number(d.ddToastDuration) : undefined,
      from: t,
    });
  });
})();


/* ===== behaviors/tooltip.js ===== */
/* Tooltip: data-dd-tooltip="Copy link" on any element shows a tooltip on mouse hover (after a short delay; instant
   while moving between tooltips) and on keyboard focus. Esc, a click, scrolling or leaving hides it.
     data-dd-tooltip-placement  top (default) · bottom · left · right, optionally -start / -end. Flips when it doesn't fit.
     data-dd-tooltip-kbd        a key hint, keys separated by spaces: "⌘ K" → <kbd>⌘</kbd><kbd>K</kbd>
   One shared .dd-tooltip (role="tooltip") lives at the end of <body>; while it is open the trigger points at it with
   aria-describedby. It takes the dawn/dusk theme of its trigger. Pointer can move onto the tooltip without losing it.
   Where the browser supports it the tooltip is a manual popover, so it shows in the top layer — above open dialogs,
   drawers and popovers whose buttons it describes. */
(() => {
  const DELAY = 450;
  const WARM = 500;
  let tip;
  let current = null;
  let showTimer = 0;
  let hideTimer = 0;
  let lastHidden = 0;
  let closeTimer = 0;
  const topLayer = typeof HTMLElement !== 'undefined' && 'showPopover' in HTMLElement.prototype;

  // Place a fixed element beside an anchor: flip to the other side if it doesn't fit, keep it 8px inside the
  // viewport and aim --dd-arrow-x / --dd-arrow-y at the anchor's centre.
  const place = (el, anchor, want = 'top', gap = 8) => {
    let [side, align = 'center'] = want.split('-');
    const a = anchor.getBoundingClientRect();
    const w = el.offsetWidth;
    const h = el.offsetHeight;
    const vw = document.documentElement.clientWidth;
    const vh = window.innerHeight;
    const m = 8;
    const room = { top: a.top - gap - h >= m, bottom: a.bottom + gap + h <= vh - m, left: a.left - gap - w >= m, right: a.right + gap + w <= vw - m };
    const flip = { top: 'bottom', bottom: 'top', left: 'right', right: 'left' };
    if (!room[side]) side = room[flip[side]] ? flip[side] : (side === 'left' || side === 'right') ? (room.top ? 'top' : 'bottom') : side;
    let x;
    let y;
    if (side === 'top' || side === 'bottom') {
      y = side === 'top' ? a.top - gap - h : a.bottom + gap;
      x = align === 'start' ? a.left : align === 'end' ? a.right - w : a.left + a.width / 2 - w / 2;
      x = Math.min(Math.max(x, m), vw - w - m);
      el.style.setProperty('--dd-arrow-x', `${Math.min(Math.max(a.left + a.width / 2 - x, 10), w - 10)}px`);
    } else {
      x = side === 'left' ? a.left - gap - w : a.right + gap;
      y = align === 'start' ? a.top : align === 'end' ? a.bottom - h : a.top + a.height / 2 - h / 2;
      y = Math.min(Math.max(y, m), vh - h - m);
      el.style.setProperty('--dd-arrow-y', `${Math.min(Math.max(a.top + a.height / 2 - y, 10), h - 10)}px`);
    }
    el.style.left = `${Math.round(x)}px`;
    el.style.top = `${Math.round(y)}px`;
    el.dataset.placement = align === 'center' ? side : `${side}-${align}`;
  };

  const ensure = () => {
    if (tip?.isConnected) return tip;
    tip = document.createElement('div');
    tip.className = 'dd-tooltip';
    tip.id = 'dd-tooltip';
    tip.setAttribute('role', 'tooltip');
    if (topLayer) tip.setAttribute('popover', 'manual');
    tip.addEventListener('pointerenter', () => clearTimeout(hideTimer));
    tip.addEventListener('pointerleave', () => hideSoon());
    document.body.append(tip);
    return tip;
  };

  const show = (el) => {
    clearTimeout(showTimer);
    clearTimeout(hideTimer);
    const text = el.getAttribute('data-dd-tooltip');
    if (!text || !el.isConnected) return;
    if (current && current !== el) release(current);
    const t = ensure();
    t.replaceChildren(Object.assign(document.createElement('span'), { textContent: text }));
    const kbd = el.getAttribute('data-dd-tooltip-kbd');
    if (kbd) {
      const keys = document.createElement('span');
      keys.className = 'dd-tooltip__keys';
      kbd.trim().split(/\s+/).forEach((k) => keys.append(Object.assign(document.createElement('kbd'), { textContent: k })));
      t.append(keys);
    }
    const scope = el.closest('[data-theme]');
    if (scope && scope !== document.documentElement) t.dataset.theme = scope.dataset.theme;
    else delete t.dataset.theme;
    clearTimeout(closeTimer);
    if (topLayer && !t.matches(':popover-open')) t.showPopover();
    const wasOpen = t.classList.contains('is-open');
    place(t, el, el.getAttribute('data-dd-tooltip-placement') || 'top');
    // Opening from closed: commit the new side first, so the fade slides in from the side it ends up on.
    if (!wasOpen) void t.offsetWidth;
    t.classList.add('is-open');
    current = el;
    if (el.getAttribute('aria-label') !== text) {
      const ids = (el.getAttribute('aria-describedby') || '').split(/\s+/).filter(Boolean);
      if (!ids.includes(t.id)) el.setAttribute('aria-describedby', [...ids, t.id].join(' '));
    }
  };

  const release = (el) => {
    const ids = (el.getAttribute('aria-describedby') || '').split(/\s+/).filter((id) => id && id !== 'dd-tooltip');
    if (ids.length) el.setAttribute('aria-describedby', ids.join(' '));
    else el.removeAttribute('aria-describedby');
  };

  const hide = () => {
    clearTimeout(showTimer);
    clearTimeout(hideTimer);
    if (!current) return;
    release(current);
    current = null;
    tip?.classList.remove('is-open');
    lastHidden = Date.now();
    // Leave the top layer once the fade-out has finished.
    clearTimeout(closeTimer);
    if (topLayer && tip) closeTimer = setTimeout(() => { if (!tip.classList.contains('is-open') && tip.matches(':popover-open')) tip.hidePopover(); }, 200);
  };
  const hideSoon = () => { clearTimeout(hideTimer); hideTimer = setTimeout(hide, 120); };

  document.addEventListener('pointerover', (e) => {
    if (e.pointerType === 'touch') return;
    const el = e.target.closest?.('[data-dd-tooltip]');
    if (!el) return;
    if (el === current) { clearTimeout(hideTimer); return; }
    clearTimeout(showTimer);
    const warm = current || Date.now() - lastHidden < WARM;
    if (warm) show(el);
    else showTimer = setTimeout(() => show(el), DELAY);
  });
  document.addEventListener('pointerout', (e) => {
    const el = e.target.closest?.('[data-dd-tooltip]');
    if (!el || el.contains(e.relatedTarget)) return;
    clearTimeout(showTimer);
    if (el === current) hideSoon();
  });
  document.addEventListener('focusin', (e) => {
    const el = e.target.closest?.('[data-dd-tooltip]');
    if (el && e.target.matches(':focus-visible')) show(el);
  });
  document.addEventListener('focusout', (e) => {
    const el = e.target.closest?.('[data-dd-tooltip]');
    if (el && el === current) hide();
  });
  document.addEventListener('pointerdown', (e) => { if (!tip?.contains(e.target)) hide(); });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && current) hide(); });
  window.addEventListener('scroll', hide, { capture: true, passive: true });
  window.addEventListener('resize', hide, { passive: true });
})();
